/* VocabHub — local-first vocabulary app. All data lives in localStorage (key below).
   Storage is isolated in load()/save() so a backend can replace it later. */
const K='vocabhub.v2',INT=[1,2,4,7,15,30,60],CAP=500; // review intervals (days), daily XP cap
const XPV={mcq:10,typ:20,scr:15,fill:15,syn:10,flash:3,match:15},WORD_XP_PER_DAY=3;
const LV=[0,100,400,900,1500,3000,6000],LN=['Beginner','Explorer','Word Seeker','Word Enthusiast','Word Master','Vocabulary Expert','Lexicon Legend'];
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const sh=a=>{a=[...a];for(let i=a.length;i>1;){const j=Math.random()*i--|0;[a[i],a[j]]=[a[j],a[i]]}return a};
const short=m=>(m||'').split(' / ')[0];
const dayOf=t=>{const d=new Date(t);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')};
let D=Object.assign({words:null,p:{},ses:[],fav:{},claims:{},ach:{},ownExamples:{},theme:'midnight',goal:20,name:'Learner'},JSON.parse(localStorage.getItem(K)||localStorage.getItem('vocabhub.v1')||'{}'));
D.ownExamples=D.ownExamples||{};
let W=D.words||[],S=null,N=10,L={q:'',st:'',cat:'',fav:false,n:50};
const save=()=>{D.words=W;try{localStorage.setItem(K,JSON.stringify(D))}catch(e){toast('Storage full or blocked: export a backup!')}};
function toast(m){const t=document.createElement('div');t.className='toast';t.textContent=m;$('#toasts').append(t);setTimeout(()=>t.remove(),3500)}
function download(n,txt,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([txt],{type}));a.download=n;a.click()}
function activeTheme(){return ({dark:'midnight',system:'midnight',light:'paper',aurora:'midnight'})[D.theme]||D.theme||'midnight'}

const DIFFICULTIES=[{id:1,name:'Beginner',tag:'Easy',desc:'Common, familiar words for a strong foundation',tone:'easy'},{id:2,name:'Elementary',tag:'Easy · Medium',desc:'Everyday and school-level vocabulary',tone:'elementary'},{id:3,name:'Intermediate',tag:'Medium',desc:'Academic and versatile vocabulary',tone:'intermediate'},{id:4,name:'Advanced',tag:'Hard',desc:'Less common words and nuanced meanings',tone:'advanced'},{id:5,name:'Expert',tag:'Very hard',desc:'Rare, literary and highly precise vocabulary',tone:'expert'}];
D.gameLevels=D.gameLevels||{};D.seen=D.seen||{};D.mist=D.mist||{};D.daily=D.daily||{};
Object.keys(D.p).forEach(id=>{const q=D.p[id];if(q&&q.i>0&&q.i>=q.c&&!D.mist[id])D.mist[id]={w:q.i,t:q.next||Date.now(),ok:0,first:q.next||Date.now()}});D.creatorName='Moshiur Rahman Araf';
