/* ---------- mistake tracking: a word is "recovered" after 3 correct answers in a row ---------- */
const mistActive=id=>{const m=D.mist[id];return !!m&&!m.fixed};
function trackMist(w,ok){const m=D.mist[w.id],now=Date.now();
 if(!ok){D.mist[w.id]={w:(m?m.w:0)+1,t:now,ok:0,first:(m&&m.first)||now}}
 else if(m&&!m.fixed){m.ok++;if(m.ok>=3){m.fixed=now;if(S)(S.rec=S.rec||[]).push(w);toast('Recovered: '+w.en)}}}
/* ---------- progress / SRS ---------- */
const gp=w=>D.p[w.id]||(D.p[w.id]={b:0,c:0,i:0,next:0,xd:'',xn:0});
const sOf=p=>!p||p.c+p.i==0?'new':(p.b>=5&&p.c>=5)?'mastered':(p.i&&p.b==0&&p.next<=Date.now())?'review':p.b>=3?'familiar':'learning';
const isDue=p=>p&&p.c+p.i>0&&p.next<=Date.now();
function grade(w,ok){trackMist(w,ok);const p=gp(w);if(ok){p.c++;if(Date.now()>=p.next){p.b++;p.next=Date.now()+INT[Math.min(p.b-1,INT.length-1)]*864e5}}else{p.i++;p.b=Math.max(0,p.b-2);p.next=Date.now()}}
function lvl(xp){let i=0;LV.forEach((v,k)=>{if(xp>=v)i=k});const n=LV[i+1];return{i,name:LN[i],next:n,pct:n?Math.round((xp-LV[i])/(n-LV[i])*100):100}}
function st(){const now=Date.now(),td=dayOf(now),o={xp:0,tc:0,ti:0,cnt:{new:0,learning:0,familiar:0,mastered:0,review:0},due:0,todayXP:0,todayC:0,todayN:0,r:0};
 const days=new Set();
 D.ses.forEach(s=>{o.xp+=s.xp||0;o.r+=s.r||0;if(s.mode!='mission'){days.add(dayOf(s.t))}if(dayOf(s.t)==td){o.todayXP+=s.xp||0;if(s.mode!='mission'){o.todayC+=s.c;o.todayN++}}});
 W.forEach(w=>{const p=D.p[w.id];o.cnt[sOf(p)]++;if(p){o.tc+=p.c;o.ti+=p.i;if(isDue(p))o.due++}});
 let s=0,d=new Date();if(!days.has(dayOf(d)))d.setDate(d.getDate()-1);while(days.has(dayOf(d))){s++;d.setDate(d.getDate()-1)}
 o.streak=s;o.days=days;o.learned=W.length-o.cnt.new;return o}
const ACH=[['First Step','Complete a practice session',s=>D.ses.some(x=>x.mode!='mission')],['First 10','Learn 10 words',s=>s.learned>=10],['First 100','Learn 100 words',s=>s.learned>=100],['Seven Day Streak','7-day streak',s=>s.streak>=7],['Thirty Day Streak','30-day streak',s=>s.streak>=30],['Perfect Score','100% in a session of 5+',s=>D.ses.some(x=>x.n>=5&&x.c==x.n&&x.mode!='mission')],['Speedster','15+ correct in a Speed Challenge',s=>D.ses.some(x=>x.mode=='speed'&&x.c>=15)],['Word Master','Master 10 words',s=>s.cnt.mastered>=10],['Memory Pro','Master 50 words',s=>s.cnt.mastered>=50],['Revision Champion','Review 100 due words',s=>s.r>=100],['Consistency Champion','Be active on 14 different days',s=>s.days.size>=14]];
function checkAch(){const s=st();ACH.forEach(([n,,f])=>{if(!D.ach[n]&&f(s)){D.ach[n]=Date.now();toast('Achievement unlocked: '+n)}})}

/* ---------- vocabulary import / export ---------- */
const nid=e=>e.toLowerCase().replace(/\s+/g,' ').trim();
function addW(list,o){const id=nid(o.en||'');if(!id)return 0;let w=list.find(x=>x.id==id);
 if(!w){if(!o.bn)return 0;list.push({id,en:o.en.trim(),bn:o.bn,pos:o.pos||'',syn:o.syn||[],ant:o.ant||[],ex:o.ex||'',ext:o.ext||'',diff:o.diff||'',cat:o.cat||'',added:Date.now()});return 1}
 if(o.bn){if(o.rep)w.bn=o.bn;else{const a=w.bn.split(/\s*\/\s*/).filter(Boolean);o.bn.split(/\s*\/\s*/).forEach(s=>{if(s&&!a.includes(s))a.push(s)});w.bn=a.join(' / ')}}
 ['pos','ex','ext','diff'].forEach(k=>{if(o[k])w[k]=o[k]});if(o.cat&&(!w.cat||w.cat=='My Vocabulary'||w.cat=='Core Collection'))w.cat=o.cat;['syn','ant'].forEach(k=>{if(o[k]&&o[k].length)w[k]=o[k]});return 2}
function csv(t){const r=[];let row=[],c='',q=false;t=t.replace(/^\uFEFF/,'');for(let i=0;i<t.length;i++){const ch=t[i];if(q){if(ch=='"'){if(t[i+1]=='"'){c+='"';i++}else q=false}else c+=ch}else if(ch=='"')q=true;else if(ch==','){row.push(c);c=''}else if(ch=='\n'||ch=='\r'){if(ch=='\r'&&t[i+1]=='\n')i++;row.push(c);r.push(row);row=[];c=''}else c+=ch}row.push(c);r.push(row);return r.filter(x=>x.join('').trim())}
const lst=s=>(s||'').split(/[;|]/).map(x=>x.trim()).filter(Boolean);
function parseInput(t){t=t.trim();const out=[];
 if(t[0]=='{'||t[0]=='['){const j=JSON.parse(t),a=Array.isArray(j)?j:j.words;a.forEach(x=>out.push({en:x.en||x.word,bn:x.bn||x.bengali_meaning,pos:x.pos||x.part_of_speech,syn:x.syn||x.synonyms,ant:x.ant||x.antonyms,ex:x.ex||x.example,ext:x.ext||x.example_translation,diff:x.diff||x.difficulty,cat:x.cat||x.category}).valueOf());return out.map(o=>(['syn','ant'].forEach(k=>{if(typeof o[k]=='string')o[k]=lst(o[k])}),o))}
 if(/^word\s*,/i.test(t)){const r=csv(t),h=r[0].map(x=>x.trim().toLowerCase());const g=(row,k)=>(row[h.indexOf(k)]||'').trim();r.slice(1).forEach(row=>out.push({en:g(row,'word'),bn:g(row,'bengali_meaning'),pos:g(row,'part_of_speech'),syn:lst(g(row,'synonyms')),ant:lst(g(row,'antonyms')),ex:g(row,'example'),ext:g(row,'example_translation'),diff:g(row,'difficulty'),cat:g(row,'category')}));return out}
 t.split(/\r?\n/).forEach(l=>{const x=l.match(/^[\s\-•*]*([^:：|]+?)\s*[:：]\s*(.+?)\s*$/);if(x&&!/^page/i.test(x[1]))out.push({en:x[1].trim(),bn:x[2].trim()})});return out}
function doImport(txt,dry){let rows;try{rows=parseInput(txt)}catch(e){return{err:'Could not read input: '+e.message}}
 const tmp=dry?JSON.parse(JSON.stringify(W)):W,r={added:0,merged:0,skipped:0,total:rows.length};rows.forEach(o=>{const x=addW(tmp,o);x==1?r.added++:x==2?r.merged++:r.skipped++});if(!dry){save()}return r}
const toCSV=()=>'\uFEFF'+[['word','bengali_meaning','part_of_speech','synonyms','antonyms','example','example_translation','difficulty','category'],...W.map(w=>[w.en,w.bn,w.pos,w.syn.join(';'),w.ant.join(';'),w.ex,w.ext,w.diff,w.cat])].map(r=>r.map(c=>'"'+String(c).replace(/"/g,'""')+'"').join(',')).join('\r\n');

/* Configure each session after opening a practice/game mode. */
function configureGame(mode,duration=0){
 if(['daily','ladder','boss'].includes(mode))return start(mode);
 const old=$('#game-setup');if(old)old.remove();
 const timed=T(mode),pairs=mode==='match'||mode==='mem',game=GAME_MODES.includes(mode);
 const counts=timed?[30,60,120]:mode==='mem'?[4,6,8]:mode==='match'?[5,8,10,12]:[5,10,20,30],def=timed?(duration||60):mode==='mem'?6:pairs?8:(counts.includes(N)?N:10);
 const unit=timed?' seconds':pairs?' pairs':mode==='flash'?' cards':' questions';
 const lvOpts=DIFFICULTIES.map(l=>{const q=wordProgress(w=>Number(w.difficulty)===l.id);return{v:l.id,t:l.name,s:l.tag+' · '+q.learned+'/'+q.t+' learned',p:q.pct}});
 const ctOpts=counts.map(n=>({v:n,t:n+unit}));
 const wrap=document.createElement('div');wrap.id='game-setup';wrap.className='setup-backdrop';
 wrap.innerHTML=`<section class="setup-panel"><button class="setup-close" onclick="this.closest('#game-setup').remove()" aria-label="Close">×</button><div class="setup-title"><span class="mode-icon">${ico(mode)}</span><div><span class="eyebrow">CUSTOMISE YOUR SESSION</span><h2>${MODE_NAME[mode]||'Practice'}</h2></div></div><p class="sub">শুরু করার আগে নিজের মতো করে Level ও ${timed?'সময়':'সংখ্যা'} বেছে নাও।</p><div class="field"><span class="field-label">Difficulty level</span>${ddHTML('setup-level',lvOpts,D.gameLevels[mode]||3)}</div><div class="field"><span class="field-label">${timed?'Challenge duration':mode==='mem'||mode==='match'?'Number of pairs':mode==='flash'?'Number of cards':'Number of questions'}</span>${ddHTML('setup-count',ctOpts,def)}</div><p class="setup-available" id="setup-available"></p><button class="btn pri setup-start" onclick="launchConfiguredGame('${mode}')">Start ${timed?'challenge':game?'game':'practice'} →</button></section>`;
 document.body.append(wrap);
 const update=()=>{const lv=+$('#setup-level').value,tot=wordsAtLevel(lv).length,fresh=unseenCount(seenKey(mode,lv),w=>Number(w.difficulty)===lv);$('#setup-available').textContent=tot+' words in this level · '+fresh+' not yet seen this round (no repeats until all have appeared)'};$('#setup-level').addEventListener('change',update);update();
}
function launchConfiguredGame(mode){const level=+$('#setup-level').value,count=+$('#setup-count').value;D.gameLevels[mode]=level;save();$('#game-setup').remove();N=T(mode)?N:count;start(mode,{level,n:T(mode)?N:count,dur:T(mode)?count:undefined});}
function saveProfileField(key,value){D[key]=value.trim();if(key==='name'&&!D.name)D.name='Learner';save();toast('Profile updated');}
function uploadProfilePhoto(file){if(!file)return;if(!file.type.startsWith('image/'))return toast('Please choose an image file');if(file.size>2*1024*1024)return toast('ছবিটি ২ MB-এর কম হতে হবে');const reader=new FileReader();reader.onload=()=>{D.profilePhoto=reader.result;save();const img=$('#profile-avatar');if(img)img.src=D.profilePhoto;toast('Profile photo updated')};reader.readAsDataURL(file);}
/* ---------- modern dropdown ---------- */
const ddLab=o=>`<span class="dd-lab"><b>${o.t}</b>${o.s?`<small>${o.s}</small>`:''}${o.p!=null?`<i class="dd-bar"><u style="width:${o.p}%"></u></i>`:''}</span>`;
function ddHTML(id,opts,val){const cur=opts.find(o=>String(o.v)===String(val))||opts[0];
 return`<div class="dd" id="dd-${id}"><input type="hidden" id="${id}" value="${cur.v}"><button type="button" class="dd-btn" onclick="ddToggle('${id}')" onkeydown="ddKey(event,'${id}')" aria-haspopup="listbox"><span class="dd-cur">${ddLab(cur)}</span><span class="dd-chev">${ico('chev')}</span></button><div class="dd-menu" role="listbox">${opts.map(o=>`<button type="button" role="option" class="dd-opt ${String(o.v)===String(cur.v)?'on':''}" data-v="${o.v}" onclick="ddPick('${id}','${o.v}')">${ddLab(o)}<span class="dd-check">${ico('check')}</span></button>`).join('')}</div></div>`}
function ddToggle(id){const d=$('#dd-'+id),open=!d.classList.contains('open');document.querySelectorAll('.dd.open').forEach(x=>x.classList.remove('open'));if(open)d.classList.add('open')}
function ddPick(id,v){const d=$('#dd-'+id),h=$('#'+id),o=[...d.querySelectorAll('.dd-opt')].find(x=>x.dataset.v===String(v));if(!o)return;d.querySelectorAll('.dd-opt').forEach(x=>x.classList.toggle('on',x===o));d.querySelector('.dd-cur').innerHTML=o.querySelector('.dd-lab').outerHTML;h.value=v;d.classList.remove('open');h.dispatchEvent(new Event('change'))}
function ddKey(e,id){const d=$('#dd-'+id);if(e.key==='Escape'){d.classList.remove('open');return}if(e.key!=='ArrowDown'&&e.key!=='ArrowUp')return;e.preventDefault();const o=[...d.querySelectorAll('.dd-opt')],i=o.findIndex(x=>x.classList.contains('on')),n=o[Math.max(0,Math.min(o.length-1,i+(e.key==='ArrowDown'?1:-1)))];if(n)ddPick(id,n.dataset.v)}
document.addEventListener('click',e=>{if(!e.target.closest('.dd'))document.querySelectorAll('.dd.open').forEach(x=>x.classList.remove('open'))});
/* ---------- question engine ---------- */
const variants=w=>w.en.split('/').map(x=>x.trim().toLowerCase()).filter(Boolean);
const okFill=w=>w.ex&&new RegExp('\\b'+variants(w)[0].replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'i').test(w.ex);
const okScr=w=>{const v=variants(w)[0];return v&&!/\s/.test(v)&&v.length>=4};
const okTyp=w=>{const v=variants(w)[0]||'';return !/\s/.test(v)&&v.length>=3&&v.length<=14&&/^[a-z-]+$/i.test(v)};
const okHang=w=>/^[a-z]{4,14}$/.test(variants(w)[0]||'');
const sentTok=w=>(w.ex||'').trim().split(/\s+/).filter(Boolean);
const okSent=w=>{const n=sentTok(w).length;return n>=4&&n<=14};
const OK={e2b:()=>1,b2e:()=>1,typ:okTyp,scr:okScr,fill:okFill,syn:w=>w.syn.length,ant:w=>w.ant.length,tf:()=>1,odd:w=>w.syn.length>=2,sent:okSent,hang:okHang};
const MODES={mcq:['e2b','b2e'],speed:['e2b','b2e'],tf:['tf'],typing:['typ'],scramble:['scr'],fill:['fill'],syn:['syn','ant'],odd:['odd'],sent:['sent'],hang:['hang'],mixed:['e2b','b2e','typ','scr','fill','syn','ant']};
const dis=(w,f,c)=>[...new Set(sh(W.filter(x=>x.id!=w.id)).map(f).filter(x=>x&&x!=c))].slice(0,3);
function mk(w,t){const o={w,t,xp:t=='e2b'||t=='b2e'||t=='tf'?'mcq':t=='ant'||t=='odd'?'syn':t=='hang'?'scr':t=='sent'?'fill':t};
 if(t=='e2b'){o.prompt=w.en;o.sub=w.pos;o.ans=short(w.bn);o.opts=sh([o.ans,...dis(w,x=>short(x.bn),o.ans)])}
 if(t=='b2e'){o.prompt=short(w.bn);o.bn=1;o.sub='Choose the English word';o.ans=w.en;o.opts=sh([w.en,...dis(w,x=>x.en,w.en)])}
 if(t=='typ'){const v=variants(w)[0].replace(/\s+/g,''),dc=sh('abcdefghijklmnopqrstuvwxyz'.split('').filter(c=>!v.includes(c))).slice(0,2);o.letters=sh([...v.toUpperCase().split(''),...dc.map(c=>c.toUpperCase())]);o.len=v.length;o.prompt=w.bn;o.bn=1;o.sub='Build the English word · 2 extra letters are decoys';o.ans=variants(w).map(x=>x.replace(/\s+/g,''));o.show=w.en;o.hint='Starts with “'+v[0].toUpperCase()+'” · '+v.length+' letters'}
 if(t=='scr'){const v=variants(w)[0];let s=v;for(let k=0;k<9&&s==v;k++)s=sh(v).join('');o.letters=s.toUpperCase().split('');o.prompt=short(w.bn);o.bn=1;o.sub='Tap the letters in the right order';o.ans=[v];o.show=v;o.hint='Starts with “'+v[0].toUpperCase()+'” · '+v.length+' letters'}
 if(t=='fill'){const v=variants(w)[0];o.prompt=w.ex.replace(new RegExp('\\b'+v.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\w*','i'),'_____');o.sub='Choose the missing word';o.ans=w.en;o.opts=sh([w.en,...dis(w,x=>x.en,w.en)])}
 if(t=='syn'||t=='ant'){const a=sh(t=='syn'?w.syn:w.ant)[0];o.prompt=w.en;o.sub='Choose the '+(t=='syn'?'synonym':'antonym');o.ans=a;const bad=[...w.syn,...w.ant,w.en];o.opts=sh([a,...[...new Set(sh(W).map(x=>x.en).filter(x=>!bad.includes(x)))].slice(0,3)])}
 if(t=='tf'){const right=Math.random()<.5,o2=sh(W).find(x=>x.id!=w.id&&short(x.bn)!=short(w.bn)),m=right||!o2?short(w.bn):short(o2.bn);o.prompt=w.en+'  =  '+m;o.bn=1;o.sub='True or false? Does the word match this meaning?';o.ans=right||!o2?'True':'False';o.opts=['True','False']}
 if(t=='odd'){const grp=[w.en,...sh(w.syn).slice(0,2)],g=grp.map(x=>x.toLowerCase()),cand=sh(W).find(x=>!g.includes(x.en.toLowerCase())&&!w.ant.includes(x.en)&&!x.syn.some(z=>g.includes(z.toLowerCase())));o.prompt='Which word does not belong?';o.sub='Three words are similar in meaning';o.ans=cand.en;o.opts=sh([...grp,cand.en])}
 if(t=='sent'){const tk=sentTok(w);let m=tk;for(let k=0;k<9&&m.join(' ')==tk.join(' ');k++)m=sh(tk);o.letters=m;o.words=1;o.len=tk.length;o.prompt=w.ext||w.bn;o.bn=1;o.long=1;o.sub='Tap the words to build the sentence';o.ans=[tk.join(' ')];o.show=tk.join(' ');o.hint='Starts with “'+tk[0]+'”'}
 if(t=='hang'){const v=variants(w)[0];o.prompt=short(w.bn);o.bn=1;o.sub='Guess the word, one letter at a time';o.ans=[v];o.show=v}
 return o}
const seenKey=(mode,level)=>mode+':'+(level||0);
function markSeen(w){if(!S||!S.key||!w)return;const a=D.seen[S.key]||(D.seen[S.key]=[]);if(!a.includes(w.id))a.push(w.id)}
/* Round-based picking: a word is not served again until every eligible word in the same game and level has appeared once. */
function pick(n,f,key){const cand=W.filter(f||(()=>1)),score=w=>{const p=D.p[w.id],k=sOf(p);return[w,(isDue(p)?3:0)+(p&&p.i>p.c?2:0)+(k=='new'?1:0)+Math.random()*2]},top=a=>a.map(score).sort((x,y)=>y[1]-x[1]).map(x=>x[0]);
 if(!key)return top(cand).slice(0,n);
 let seen=new Set(D.seen[key]||[]),fresh=cand.filter(w=>!seen.has(w.id));
 if(!fresh.length){D.seen[key]=[];seen=new Set();fresh=cand}
 const a=top(fresh).slice(0,n);
 if(a.length<n){D.seen[key]=[];const ids=new Set(a.map(w=>w.id));a.push(...top(cand.filter(w=>!ids.has(w.id))).slice(0,n-a.length))}
 return a}
const unseenCount=(key,f)=>{const seen=new Set(D.seen[key]||[]);return W.filter(f||(()=>1)).filter(w=>!seen.has(w.id)).length}
function award(w,key){const p=gp(w),td=dayOf(Date.now());if(p.xd!=td){p.xd=td;p.xn=0}if(p.xn>=WORD_XP_PER_DAY||st().todayXP+S.xp>=CAP)return 0;p.xn++;return XPV[key]}

/* ---------- sessions ---------- */
function start(mode,o={}){const n=o.n||N;if(W.length<4)return toast('Add at least 4 words in Admin first.');
 clearInterval(S&&S.iv);S={mode,i:0,c:0,xp:0,r:0,bad:[],t0:Date.now(),n,n0:n,dur:o.dur,key:o.due?null:seenKey(mode,o.level)};
 if(mode=='match'){S.ws=pick(Math.min(n, W.length),null,S.key);S.L=sh(S.ws);S.R=sh(S.ws);S.sel=null;S.done=new Set();S.miss=new Set();S.n=S.ws.length;go('play');return}
 if(mode=='flash'){S.ws=o.due?pick(n,w=>isDue(D.p[w.id])):pick(n,null,S.key);if(!S.ws.length)return toast('Nothing due right now — great job!');S.n=S.ws.length;S.rev=0;go('play');return}
 if(mode=='mem'){const k=Math.min(n,W.length);S.ws=pick(k,null,S.key);if(S.ws.length<3)return toast('Not enough words.');S.cards=sh(S.ws.flatMap(w=>[{id:w.id,w,side:'en'},{id:w.id,w,side:'bn'}]));S.open=[];S.matched=new Set();S.missed=new Set();S.moves=0;S.lock=0;S.n=S.ws.length;go('play');return}
 const types=MODES[mode],mix=mode=='mixed';let qs=[];
 if(T(mode)){const seen=new Set(D.seen[S.key]||[]);let fr=W.filter(w=>!seen.has(w.id));if(!fr.length){D.seen[S.key]=[];fr=W}const ws=[...sh(fr),...sh(W.filter(w=>!fr.includes(w)))];for(let i=0;i<300;i++)qs.push(mk(ws[i%ws.length],types[Math.random()*types.length|0]));S.n=0;S.end=Date.now()+o.dur*1000;S.iv=setInterval(tick,250)}
 else{const ws=pick(n,w=>mix||types.some(t=>OK[t](w)),S.key);if(ws.length<(mix?1:3)){return toast(mode=='fill'||mode=='sent'?'Need more words with example sentences.':mode=='syn'||mode=='odd'?'Need more words with synonyms/antonyms.':mode=='hang'?'Need more single words (4+ letters).':mode=='scramble'?'Need more single-word entries (4+ letters).':'Not enough words.')}
  qs=ws.map(w=>{const el=types.filter(t=>OK[t](w));return mk(w,el[Math.random()*el.length|0])});S.n=qs.length}
 S.qs=qs;go('play')}
function tick(){const e=$('#tm');if(!e)return;const l=Math.max(0,Math.ceil((S.end-Date.now())/1000));e.textContent=l+'s';if(l<=0)finish()}
function answer(ok){const q=S.qs[S.i],p=gp(q.w),due=isDue(p);grade(q.w,ok);markSeen(q.w);if(S.mode=='boss'&&!ok)S.lives--;if(S.lad)ladAdvance(ok);if(due)S.r++;S.att=(S.att||0)+1;
 if(ok){S.c++;if(!T(S.mode))S.xp+=award(q.w,q.xp)}else S.bad.push(q.w);save()}
function pickOpt(i){const q=S.qs[S.i];if(S.fb)return;const ok=q.opts[i]==q.ans;answer(ok);S.fb=1;
 if(T(S.mode)){S.i++;S.fb=0;if(S.i>=S.qs.length)return finish();return render()}
 document.querySelectorAll('.opt').forEach((b,k)=>{b.disabled=true;if(q.opts[k]==q.ans)b.classList.add('ok');else if(k==i)b.classList.add('no')});
 $('#fb').outerHTML=fbHTML(ok,q.ans)}
const fbHTML=(ok,a)=>`<div id="fb" class="fb ${ok?'ok':'no'}">${ok?'Correct!':'Not quite. Answer: <b>'+esc(a)+'</b>'}</div><button class="btn pri next-btn" onclick="next()">${(S.mode=='ladder'?S.i+1>=S.n:S.i+1>=S.qs.length)||S.lives===0?'Finish':'Next'}</button>`;
function submitTyped(){const q=S.qs[S.i];if(S.fb)return;const v=$('#in').value.trim().toLowerCase().replace(/\s+/g,' ');if(!v)return;const ok=q.ans.includes(v);answer(ok);S.fb=1;$('#in').disabled=true;$('#fb').outerHTML=fbHTML(ok,q.show)}
function hint(){S.hinted=1;$('#hint').textContent='Hint: '+S.qs[S.i].hint}
function next(){S.i++;S.fb=0;S.hinted=0;if(S.mode=='ladder'&&S.i<S.n&&S.qs.length<=S.i)S.qs.push(ladderQ());(S.i>=(S.mode=='ladder'?S.n:S.qs.length)||S.lives===0)?finish():render()}
function finish(){if(!S||S.done_)return;S.done_=1;clearInterval(S.iv);const b4=lvl(st().xp).i;
 if(T(S.mode))S.xp=Math.min(25,S.c*2);if(S.mode=='boss'&&S.lives>0)S.xp+=15;if(S.mode=='daily'){const dk=dayOf(Date.now());if(!D.daily[dk])S.xp+=15;D.daily[dk]={c:S.c,n:S.n,t:Date.now()}}if(S.lad)S.level=S.lad.peak;
 const n=T(S.mode)?S.att||0:S.n;D.ses.push({t:Date.now(),mode:S.mode,n,c:S.c,xp:S.xp,ms:Date.now()-S.t0,r:S.r,lv:S.level||0,bad:[...new Set(S.bad.map(w=>w.id))].slice(0,25)});save();
 const a=lvl(st().xp).i;if(a>b4)toast('⬆ Level up! You are now '+LN[a]);checkAch();save();S.fin=1;render()}
function matchClick(side,i){if(S.done_)return;const w=side=='L'?S.L[i]:S.R[i];if(S.done.has(w.id))return;
 if(side=='L'){S.sel=w;return render()}if(!S.sel)return;
 if(S.sel.id==w.id){S.done.add(w.id);markSeen(w);S.c++;grade(w,!S.miss.has(w.id));if(!S.miss.has(w.id))S.xp+=0;S.sel=null;if(S.done.size==S.ws.length){S.xp=Math.min(S.xp+award(w,'match'),CAP);return finish()}}else{S.miss.add(S.sel.id);S.miss.add(w.id);S.bad.push(S.sel);S.sel=null;toast('Not a match')}save();render()}
function flashAns(ok){const w=S.ws[S.i];grade(w,ok);markSeen(w);if(ok){S.c++;S.xp+=award(w,'flash')}else S.bad.push(w);if(isDue(D.p[w.id])&&ok)S.r++;S.i++;S.rev=0;save();S.i>=S.ws.length?finish():render()}
function flashWord(id){const w=W.find(x=>x.id===id);if(!w)return;closeWord();clearInterval(S&&S.iv);S={mode:'flash',i:0,c:0,xp:0,r:0,bad:[],t0:Date.now(),n:1,ws:[w],rev:0};go('play')}


/* ---------- tile games: scramble · word builder · sentence builder ---------- */
function scrState(q){if(!S.scr||S.scr.i!==S.i)S.scr={i:S.i,slots:Array(q.len||q.letters.length).fill(-1),res:''};return S.scr}
function scrHTML(q){const sc=scrState(q),used=new Set(sc.slots);
 const slots=sc.slots.map((ix,k)=>`<button class="scr-slot ${ix<0?'':'filled'} ${sc.res}" ${S.fb||ix<0?'disabled':''} onclick="scrRemove(${k})" aria-label="Slot ${k+1}">${ix<0?'':esc(q.letters[ix])}</button>`).join('');
 const tiles=q.letters.map((ch,ix)=>`<button class="scr-tile" ${used.has(ix)||S.fb?'disabled':''} onclick="scrPlace(${ix})">${esc(ch)}</button>`).join('');
 return`<div id="scr" class="${q.words?'scr-wide':''}"><div class="scr-slots">${slots}</div><div class="scr-bank">${tiles}</div><div class="row scr-actions"><button class="btn pri" onclick="scrCheck()" ${S.fb?'disabled':''}>Check</button><button class="btn" onclick="scrBack()" ${S.fb?'disabled':''}>Undo</button><button class="btn" onclick="scrClear()" ${S.fb?'disabled':''}>Clear</button><button class="btn" onclick="hint()">Hint</button></div><p class="sub" id="hint"></p></div>`}
function scrPaint(){const q=S.qs[S.i],box=$('#scr');if(!box)return;const h=$('#hint')?$('#hint').textContent:'';box.outerHTML=scrHTML(q);if(h&&$('#hint'))$('#hint').textContent=h}
function scrPlace(ix){if(S.fb)return;const sc=scrState(S.qs[S.i]),k=sc.slots.indexOf(-1);if(k<0||sc.slots.includes(ix))return;sc.slots[k]=ix;scrPaint()}
function scrRemove(k){if(S.fb)return;scrState(S.qs[S.i]).slots[k]=-1;scrPaint()}
function scrBack(){if(S.fb)return;const sc=scrState(S.qs[S.i]);for(let k=sc.slots.length-1;k>=0;k--)if(sc.slots[k]>=0){sc.slots[k]=-1;break}scrPaint()}
function scrClear(){if(S.fb)return;scrState(S.qs[S.i]).slots.fill(-1);scrPaint()}
function scrCheck(){if(S.fb)return;const q=S.qs[S.i],sc=scrState(q);if(sc.slots.includes(-1))return toast('আগে সবগুলো ঘর পূরণ করো');
 const val=sc.slots.map(i=>q.letters[i]).join(q.words?' ':''),sorted=x=>x.split('').sort().join('');let ok;
 if(q.words)ok=val===q.ans[0];else{const lv=val.toLowerCase();ok=q.ans.includes(lv)||(q.t=='scr'&&sorted(lv)===sorted(q.ans[0])&&W.some(x=>variants(x).includes(lv)))}
 answer(ok);S.fb=1;sc.res=ok?'ok':'no';scrPaint();$('#fb').outerHTML=fbHTML(ok,q.show)}
/* ---------- hangman ---------- */
function hgState(){if(!S.hg||S.hg.i!==S.i)S.hg={i:S.i,g:[],wrong:0};return S.hg}
function hgHTML(q){const h=hgState(),v=q.ans[0],over=!!S.fb;
 const slots=v.split('').map(ch=>{const on=h.g.includes(ch);return`<span class="hg-slot ${on?'on':''} ${over&&!on?'miss':''}">${on||over?ch.toUpperCase():''}</span>`}).join('');
 const hearts=Array.from({length:6},(_,i)=>`<span class="heart ${i<6-h.wrong?'full':''}">${ico('heart')}</span>`).join('');
 const keys='abcdefghijklmnopqrstuvwxyz'.split('').map(ch=>{const u=h.g.includes(ch);return`<button class="hg-key ${u?(v.includes(ch)?'ok':'no'):''}" ${u||over?'disabled':''} onclick="hgGuess('${ch}')">${ch.toUpperCase()}</button>`}).join('');
 return`<div id="hg"><div class="hearts" aria-label="${6-h.wrong} wrong guesses left">${hearts}</div><div class="scr-slots hg-slots">${slots}</div><div class="hg-keys">${keys}</div></div>`}
function hgGuess(ch){if(S.fb)return;const q=S.qs[S.i],h=hgState(),v=q.ans[0];if(h.g.includes(ch))return;h.g.push(ch);if(!v.includes(ch))h.wrong++;
 const win=v.split('').every(c=>h.g.includes(c)),lose=h.wrong>=6;if(win||lose){answer(win);S.fb=1}
 $('#hg').outerHTML=hgHTML(q);if(win||lose)$('#fb').outerHTML=fbHTML(win,q.show)}
/* ---------- memory flip ---------- */
function memBody(){return`<div id="mem-wrap"><p class="sub">Moves: <b>${S.moves}</b> · Pairs found: <b>${S.matched.size}/${S.ws.length}</b></p><div class="mem-grid">${S.cards.map((c,k)=>{const open=S.open.includes(k)||S.matched.has(c.id);return`<button class="mem-card ${open?'open':''} ${S.matched.has(c.id)?'done':''} ${c.side=='bn'?'bn':''}" onclick="memFlip(${k})" ${S.matched.has(c.id)?'disabled':''} aria-label="Card ${k+1}"><span class="mem-back">${ico('spark')}</span><span class="mem-front">${esc(c.side=='en'?c.w.en:short(c.w.bn))}</span></button>`}).join('')}</div></div>`}
const memHTML=()=>`<h1>Memory Flip</h1><p class="sub">Turn two cards at a time — match each English word with its Bengali meaning.</p>${memBody()}`;
function memFlip(k){if(S.lock||S.fin)return;const c=S.cards[k];if(S.matched.has(c.id)||S.open.includes(k))return;S.open.push(k);
 if(S.open.length==2){S.moves++;const[a,b]=S.open.map(i=>S.cards[i]);
  if(a.id==b.id&&a.side!=b.side){S.matched.add(a.id);S.c++;grade(a.w,!S.missed.has(a.id));markSeen(a.w);S.open=[];save();$('#mem-wrap').outerHTML=memBody();if(S.matched.size==S.ws.length){S.xp=Math.min(award(S.ws[0],'match'),CAP);S.n=Math.max(S.moves,S.ws.length);finish()}}
  else{S.missed.add(a.id);S.missed.add(b.id);S.bad.push(a.w,b.w);S.lock=1;$('#mem-wrap').outerHTML=memBody();setTimeout(()=>{S.open=[];S.lock=0;const m=$('#mem-wrap');if(m)m.outerHTML=memBody()},850)}}
 else $('#mem-wrap').outerHTML=memBody()}
/* ---------- ladder · boss · daily · mistakes exam ---------- */
const hudExtra=()=>S.mode=='boss'?' · <span class="hearts inline">'+Array.from({length:3},(_,i)=>`<span class="heart ${i<S.lives?'full':''}">${ico('heart')}</span>`).join('')+'</span>':S.lad?' · Level '+S.lad.lv+' '+DIFFICULTIES[S.lad.lv-1].name+' · streak '+S.lad.streak+'/3':'';
const QTYPES=['e2b','b2e','typ','scr','fill','syn','ant','odd','sent'];
const qFor=w=>{const el=QTYPES.filter(t=>OK[t](w));return mk(w,el[Math.random()*el.length|0])};
function ladAdvance(ok){const l=S.lad;if(ok){l.streak++;if(l.streak>=3&&l.lv<5){l.lv++;l.streak=0;l.peak=Math.max(l.peak,l.lv);toast('Level up! '+DIFFICULTIES[l.lv-1].name)}}else{l.streak=0;if(l.lv>1)l.lv--}}
function ladderQ(){const lv=S.lad.lv;S.key='ladder:'+lv;const w=pick(1,x=>Number(x.difficulty)===lv,S.key)[0]||pick(1)[0],t=lv<3?['e2b','b2e']:['e2b','b2e','typ','fill','syn'].filter(x=>OK[x](w));return mk(w,t[Math.random()*t.length|0])}
const seeded=n=>{let a=n>>>0;return()=>{a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}};
const hashStr=x=>{let h=2166136261;for(const c of x){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0};
function dailyWords(){const r=seeded(hashStr(dayOf(Date.now())+'-vocabhub')),a=[...W].sort((x,y)=>x.id<y.id?-1:1);for(let i=a.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a.slice(0,5)}
function hardWords(n){const act=W.filter(w=>mistActive(w.id)).sort((a,b)=>D.mist[b.id].w-D.mist[a.id].w),hard=sh(W.filter(w=>!act.includes(w)&&D.p[w.id]&&D.p[w.id].i>D.p[w.id].c)),rest=sh(W.filter(w=>!act.includes(w)&&!hard.includes(w)&&(!D.p[w.id]||D.p[w.id].b<3)));return[...act,...hard,...rest].slice(0,n)}
function startSpecial(mode,o={}){clearInterval(S&&S.iv);if(W.length<4)return toast('Add at least 4 words in Admin first.');
 const base={mode,i:0,c:0,xp:0,r:0,bad:[],t0:Date.now(),key:null,level:0};
 if(mode=='mistakes'){const ws=W.filter(w=>mistActive(w.id)).sort((a,b)=>D.mist[b.id].w-D.mist[a.id].w).slice(0,o.n||10);if(!ws.length)return toast('ভুল করা কোনো শব্দ নেই — দারুণ!');S={...base,n:ws.length,n0:o.n||10,qs:sh(ws).map(qFor)}}
 else if(mode=='boss'){S={...base,n:10,n0:10,lives:3,qs:sh(hardWords(10)).map(qFor)}}
 else if(mode=='daily'){S={...base,n:5,n0:5,qs:dailyWords().map(qFor)}}
 else if(mode=='ladder'){S={...base,n:15,n0:15,lad:{lv:1,streak:0,peak:1},qs:[]};S.qs.push(ladderQ())}
 go('play')}
function startMistakeExam(){const n=+($('#mx-count')?$('#mx-count').value:10)||10;start('mistakes',{n})}

document.addEventListener('keydown',e=>{if(!S||S.fin||location.hash!=='#play'||!S.qs)return;const q=S.qs[S.i];if(!q||!(q.letters||q.t=='hang'))return;
 if(e.target&&/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.ctrlKey||e.metaKey||e.altKey)return;
 if(e.key==='Enter'){e.preventDefault();S.fb?next():(q.letters&&scrCheck());return}
 if(S.fb||e.key.length!==1&&e.key!=='Backspace')return;
 if(q.t=='hang'){if(/^[a-z]$/i.test(e.key))hgGuess(e.key.toLowerCase());return}
 if(q.words)return;
 if(e.key==='Backspace'){e.preventDefault();scrBack();return}
 const sc=scrState(q),used=new Set(sc.slots),ix=q.letters.findIndex((c,k)=>!used.has(k)&&c.toLowerCase()===e.key.toLowerCase());if(ix>=0){e.preventDefault();scrPlace(ix)}});
