V.lib=()=>`<div class="page-heading"><div><span class="eyebrow">YOUR PERSONAL WORD BANK</span><h1>Vocabulary library</h1><p class="sub">Search, save and explore every word in your collection.</p></div><span class="count-tile"><b>${W.length}</b><small>WORDS</small></span></div>${W.length?`<div class="library-toolbar"><input id="q" placeholder="⌕  Search English or Bengali" value="${esc(L.q)}" oninput="L.q=this.value;L.n=50;drawLib()"><select aria-label="Filter by learning status" onchange="L.st=this.value;L.n=50;drawLib()">${['','new','learning','familiar','mastered','review'].map(x=>`<option value="${x}" ${L.st==x?'selected':''}>${x||'All status'}</option>`).join('')}</select><select aria-label="Filter by difficulty" onchange="D.libraryDifficulty=+this.value||0;L.n=50;drawLib()">${[['','All levels'],...DIFFICULTIES.map(x=>[x.id,x.name])].map(([x,n])=>`<option value="${x}" ${(Number(D.libraryDifficulty||0)===Number(x))?'selected':''}>${n}</option>`).join('')}</select><select aria-label="Filter by topic" onchange="L.cat=this.value;L.n=50;drawLib()">${['',...Array.from(new Set(W.map(w=>w.cat).filter(Boolean))).sort()].map(x=>`<option value="${esc(x)}" ${L.cat==x?'selected':''}>${x||'All topics'}</option>`).join('')}</select><label class="favorite-filter"><input type="checkbox" ${L.fav?'checked':''} onchange="L.fav=this.checked;drawLib()"> Favorites</label><button class="btn" onclick="rnd()">Surprise me ✦</button></div><div class="library-meta"><span id="lib-count">Showing your words</span><span>Tap a word to see its details</span></div><div id="list" class="library-list"></div>`:empty()}`;
function drawLib(){const q=L.q.toLowerCase(),a=W.map((w,i)=>[w,i]).filter(([w])=>(!q||w.en.toLowerCase().includes(q)||w.bn.includes(q))&&(!L.st||sOf(D.p[w.id])==L.st)&&(!L.cat||w.cat==L.cat)&&(!D.libraryDifficulty||Number(w.difficulty)===Number(D.libraryDifficulty))&&(!L.fav||D.fav[w.id])).sort((x,y)=>x[0].en.localeCompare(y[0].en));
 $('#list').innerHTML=a.slice(0,L.n).map(([w,i])=>`<article class="word-row" id="w${i}"><button class="word-row-open" data-word="${esc(w.id)}" onclick="openWord(this.dataset.word)"><span class="word-row-title"><b>${esc(w.en)}</b><small class="bn">${esc(w.bn)}</small></span><span class="word-row-side"><span class="chip status-${sOf(D.p[w.id])}">${sOf(D.p[w.id])}</span><span class="expand-mark">↗</span></span></button><button class="word-row-fav" aria-label="${D.fav[w.id]?'Remove from saved words':'Save word'}" title="${D.fav[w.id]?'Remove from saved words':'Save word'}" onclick="fav(${i})">${D.fav[w.id]?'★':'☆'}</button></article>`).join('')||'<div class="empty">No words match these filters.</div>';
 const count=$('#lib-count');if(count)count.textContent=`${a.length} matching words · ${L.n<a.length?`Showing ${Math.min(L.n,a.length)}`:'All results visible'}`;
 if(a.length>L.n)$('#list').insertAdjacentHTML('beforeend','<button class="btn" onclick="L.n+=50;drawLib()">Show more ('+(a.length-L.n)+')</button>')}
function fav(i){const id=W[i].id;D.fav[id]?delete D.fav[id]:D.fav[id]=1;save();drawLib();const b=$('#profile-save');if(b)b.textContent=D.fav[id]?'★ Saved to Library':'☆ Save word'}
function rnd(){const pool=W.filter(w=>!L.cat||w.cat==L.cat);const w=pool[Math.random()*pool.length|0]||W[0];if(w)openWord(w.id)}
function openTopic(cat){L.cat=cat;L.q='';L.st='';L.fav=false;L.n=50;go('lib')}
function inferredPos(w){
 const raw=(w.pos||'').trim();if(raw)return {value:raw,inferred:false};
 const x=(w.en||'').toLowerCase(),bn=w.bn||'';
 if(/(tion|sion|ment|ness|ity|ance|ence|ship|hood|ism|ist|er|or|logy|graphy|ure|acy|dom)$/.test(x))return {value:'noun',inferred:true};
 if(/ly$/.test(x)&&!/(family|lovely|lonely|lively|likely|friendly)$/.test(x))return {value:'adverb',inferred:true};
 if(/(able|ible|ful|less|ous|ive|al|ic|ary|ent|ant|ical|ish|ed|ing)$/.test(x))return {value:'adjective',inferred:true};
 if(/(ize|ise|ify|ate|en)$/.test(x)||/(করা|হওয়া|হওয়া|থাকা|যাওয়া|যাওয়া|দেওয়া|দেওয়া|পাওয়া|পাওয়া|বলা|রাখা|ধরা)/.test(bn))return {value:'verb',inferred:true};
 return {value:'general',inferred:true};
}
function posMeaning(pos){
 const p=(pos||'').toLowerCase();
 if(p.includes('noun')&&!p.includes('verb'))return 'বিশেষ্য · ব্যক্তি, বস্তু, স্থান বা ধারণার নাম বোঝায়।';
 if(p.includes('verb')&&!p.includes('noun'))return 'ক্রিয়া · কোনো কাজ, অবস্থা বা ঘটনা বোঝায়।';
 if(p.includes('adjective'))return 'বিশেষণ · কোনো ব্যক্তি বা বস্তুর বৈশিষ্ট্য বর্ণনা করে।';
 if(p.includes('adverb'))return 'ক্রিয়া বিশেষণ · কাজটি কীভাবে, কখন বা কতটা হচ্ছে তা বোঝাতে সাহায্য করে।';
 if(p.includes('noun')&&p.includes('verb'))return 'বিশেষ্য ও ক্রিয়া—দুইভাবেই ব্যবহৃত হতে পারে; বাক্যের অবস্থান দেখে অর্থ বুঝুন।';
 return 'শব্দটির নির্দিষ্ট word class এখনো যোগ করা হয়নি। বাক্যের প্রসঙ্গ দেখে এর ব্যবহার নির্ধারণ করুন।';
}
const RICH=[['ipa','PRONUNCIATION (IPA)'],['def','ENGLISH DEFINITION'],['forms','WORD FORMS'],['coll','COLLOCATIONS'],['usage','COMMON USAGE'],['mistake','COMMON MISTAKES'],['ety','ORIGIN'],['rel','RELATED EXPRESSIONS']];
function richCards(w){const c=RICH.filter(([k])=>w[k]&&(!Array.isArray(w[k])||w[k].length)).map(([k,t])=>`<section class="word-profile-card"><span class="word-profile-label">${t}</span><div class="word-related-list">${[].concat(w[k]).map(x=>`<span class="word-related-chip">${esc(x)}</span>`).join('')}</div></section>`).join('');return c?`<div class="word-profile-grid">${c}</div>`:''}
function wordProfileHTML(w){
 const pos=inferredPos(w),pLabel=pos.value==='general'?'Word class not specified':pos.value.split('/').map(x=>x.trim()).join(' / ');
 const meanings=(w.bn||'অর্থ যোগ করা হয়নি').split(/\s*\/\s*/).filter(Boolean);
 const curated=!!(w.ex&&w.ex.trim()),example=curated?w.ex:'';
 const translation=curated?(w.ext||''):`“${w.en}” শব্দটির বাংলা অর্থ “${w.bn}”।`;
 const syn=(w.syn||[]).filter(Boolean),ant=(w.ant||[]).filter(Boolean);
 const related=(arr)=>arr.length?arr.map(x=>{const target=W.find(z=>z.en.toLowerCase()===String(x).toLowerCase());return target?`<button class="word-related-chip" data-word="${esc(target.id)}" onclick="openWord(this.dataset.word)">${esc(x)} ↗</button>`:`<span class="word-related-chip">${esc(x)}</span>`}).join(''):'<span class="word-empty-note">এখনো কোনো শব্দ যোগ করা হয়নি</span>';
 const own=D.ownExamples[w.id]||'';
 return `<div class="word-profile-head"><div class="word-profile-topline"><span class="word-profile-kicker">✦ VOCABULARY PROFILE</span><button class="word-profile-close" onclick="closeWord()" aria-label="Close details">×</button></div><h2 class="word-profile-title">${esc(w.en)}</h2><div class="word-profile-meta"><span>${esc(pLabel)}${pos.inferred?' · inferred':''}</span><span>${esc(w.cat||'General vocabulary')}</span><span>${esc(levelTag(w))}</span></div><div class="word-profile-meaning-label">বাংলা অর্থ</div><div class="word-profile-meaning bn">${esc(w.bn||'অর্থ যোগ করা হয়নি')}</div></div>
 <div class="word-profile-grid"><section class="word-profile-card"><span class="word-profile-label">MEANING BREAKDOWN</span><div class="meaning-chips">${meanings.map(x=>`<span class="meaning-chip bn">${esc(x)}</span>`).join('')}</div><p class="word-profile-bn-note bn">${esc(posMeaning(pos.value))}</p></section><section class="word-profile-card"><span class="word-profile-label">WORD INFORMATION</span><div class="word-info-line"><span>Part of speech</span><b>${esc(pLabel)}${pos.inferred?'*':''}</b></div><div class="word-info-line"><span>Collection</span><b>${esc(w.cat||'General')}</b></div><div class="word-info-line"><span>Learning level</span><b>${esc(levelTag(w))}</b></div>${pos.inferred?'<p class="word-profile-footnote">* Word class is estimated from the word form and Bengali meaning; it has not been individually verified.</p>':''}</section></div>
 ${curated?`<section class="word-profile-card word-example-card"><div class="word-card-heading"><span class="word-profile-label">USAGE EXAMPLE</span><span class="word-card-icon">Aa</span></div><p class="word-example-large">“${esc(example)}”</p><p class="bn word-example-translation">${esc(translation||'')}</p></section>`:''}
 ${richCards(w)}
 ${w.sources&&w.sources.length?`<section class="word-profile-card word-source-card"><span class="word-profile-label">REFERENCE LINKS · ENTRY CHECK</span><div class="word-related-list">${w.sources.map(s=>`<a class="word-related-chip" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.name)} ↗</a>`).join('')}</div>${w.ipa?`<p class="word-profile-footnote">IPA shown above is General American pronunciation transcribed from the CMU Pronouncing Dictionary; it is not an Oxford/Cambridge IPA verification.</p>`:''}<p class="word-profile-footnote">Reference links are lookup links. Entries have not yet been individually checked against these dictionaries.</p></section>`:''}
 <div class="word-profile-grid"><section class="word-profile-card"><span class="word-profile-label">SYNONYMS · সমার্থক</span><div class="word-related-list">${related(syn)}</div></section><section class="word-profile-card"><span class="word-profile-label">ANTONYMS · বিপরীতার্থক</span><div class="word-related-list">${related(ant)}</div></section></div>
 <div class="word-profile-actions"><button id="profile-save" class="btn" onclick="toggleWordSave('${esc(w.id)}')">${D.fav[w.id]?'★ Saved to Library':'☆ Save word'}</button><button class="btn pri" data-word="${esc(w.id)}" onclick="flashWord(this.dataset.word)">Practice this word ↗</button></div>`;
}
function ensureWordModal(){let root=$('#word-modal-root');if(!root){root=document.createElement('div');root.id='word-modal-root';document.body.append(root)}return root}
function openWord(id){const w=W.find(x=>x.id===id);if(!w)return;const root=ensureWordModal();root.innerHTML=`<div class="word-modal-backdrop" onclick="if(event.target===this)closeWord()"><section class="word-dialog" role="dialog" aria-modal="true" aria-label="${esc(w.en)} word details">${wordProfileHTML(w)}</section></div>`;document.body.classList.add('word-modal-open');root.style.display='block';const close=root.querySelector('.word-profile-close');if(close)close.focus()}
function closeWord(){const root=$('#word-modal-root');if(root){root.style.display='none';root.innerHTML=''}document.body.classList.remove('word-modal-open')}
function toggleWordSave(id){D.fav[id]?delete D.fav[id]:D.fav[id]=1;save();const b=$('#profile-save');if(b)b.textContent=D.fav[id]?'★ Saved to Library':'☆ Save word';if($('#list'))drawLib();toast(D.fav[id]?'Added to saved words':'Removed from saved words')}
