V.practice=()=>{const list=[['mcq','Multiple choice','Quick English ↔ Bengali recall'],['fill','Fill in the blanks','Use words naturally in context'],['match','Word matching','Connect English words to their Bengali meanings'],['syn','Synonym & antonym','Explore similar and opposite meanings'],['flash','Flashcard recall','Reveal, remember and self-check'],['mixed','Mixed practice','A smart blend of available question types']],na=Object.values(D.mist).filter(m=>!m.fixed).length;return`<div class="page-heading"><div><span class="eyebrow">BUILD STRONGER RECALL</span><h1>Practice studio</h1><p class="sub">Choose a format, sharpen your memory and earn XP as you go.</p></div><span class="count-tile"><b>${String(list.length).padStart(2,'0')}</b><small>MODES</small></span></div>${progressCard()}<a class="card mist-banner" href="#mistakes"><span class="mode-icon">${ico('mistakes')}</span><div><b>${na?na+' words to fix':'No mistakes to fix'}</b><small>${na?'Take a mistakes exam built from your wrong answers →':'Your wrong answers will collect in the Mistakes tab.'}</small></div></a>${modeCards(list,'Start practice')}`};
