V.topics=()=>{const descriptions={'Academic':'Build precise, formal vocabulary for study and writing.','Communication':'Express ideas clearly in speaking and writing.','Character':'Describe personality, attitude and behaviour.','Personal Growth':'Words for goals, improvement and resilience.','Society & Life':'Explore words about people, communities and everyday life.','Science & Nature':'Discover useful terms for science and the natural world.','Core Collection':'Your original saved vocabulary collection.'};const symbols={'Academic':'⌘','Communication':'✉','Character':'◈','Personal Growth':'↗','Society & Life':'◎','Science & Nature':'✧','Core Collection':'Aa'};const cats=[...new Set(W.map(w=>w.cat||'Core Collection'))].sort((a,b)=>a.localeCompare(b));return`<div class="page-heading"><div><span class="eyebrow">CURATED LEARNING COLLECTIONS</span><h1>Explore study paths</h1><p class="sub">Choose a topic and learn words in a meaningful context.</p></div><span class="count-tile"><b>${cats.length}</b><small>TOPICS</small></span></div><div class="topic-catalog">${cats.map((cat,i)=>{const a=W.filter(w=>w.cat===cat);return`<article class="catalog-card catalog-${i%6}"><div class="catalog-top"><span class="catalog-icon">${symbols[cat]||'✦'}</span><span class="soft-pill">${a.length} WORDS</span></div><h2>${esc(cat)}</h2><p>${descriptions[cat]||'Explore a focused collection of useful vocabulary and examples.'}</p><div class="catalog-footer"><span>${a.filter(w=>w.ex).length} example-rich words</span><button class="btn pri" data-topic="${esc(cat)}" onclick="openTopic(this.dataset.topic)">Explore topic ↗</button></div></article>`}).join('')}</div><section class="study-note"><span class="note-mark">✦</span><div><b>Study with a plan</b><p>Start with a topic, learn a few words, then use Smart Practice to strengthen recall. Your progress is saved automatically on this device.</p></div></section>`};
