function achMeter(n,s){const done=!!D.ach[n];let v=0,g=1;switch(n){case'First Step':v=D.ses.some(x=>x.mode!='mission')?1:0;break;case'First 10':v=s.learned;g=10;break;case'First 100':v=s.learned;g=100;break;case'Seven Day Streak':v=s.streak;g=7;break;case'Thirty Day Streak':v=s.streak;g=30;break;case'Perfect Score':v=D.ses.some(x=>x.n>=5&&x.c==x.n&&x.mode!='mission')?1:0;break;case'Speedster':v=Math.max(0,...D.ses.filter(x=>x.mode=='speed').map(x=>x.c));g=15;break;case'Word Master':v=s.cnt.mastered;g=10;break;case'Memory Pro':v=s.cnt.mastered;g=50;break;case'Revision Champion':v=s.r;g=100;break;case'Consistency Champion':v=s.days.size;g=14;break;}return{done,v:Math.min(v,g),g,pct:Math.min(100,Math.round(v/g*100))}}
V.achievements=()=>{const s=st(),unlocked=ACH.filter(([n])=>D.ach[n]).length;return`<div class="page-heading"><div><span class="eyebrow">MILESTONES & REWARDS</span><h1>Achievements</h1><p class="sub">Every milestone reflects real progress. Keep learning to unlock the next one.</p></div><div class="count-tile"><b>${unlocked}/${ACH.length}</b><small>UNLOCKED</small></div></div><section class="ach-summary card"><div class="ach-summary-icon">${ico('trophy')}</div><div class="ach-summary-copy"><span class="eyebrow">YOUR COLLECTION</span><b>${unlocked===ACH.length?'All milestones collected!':`${unlocked} milestone${unlocked===1?'':'s'} unlocked`}</b><small>${ACH.length-unlocked} more to discover</small></div><div class="ach-summary-ring" style="--p:${Math.round(unlocked/ACH.length*100)}%"><span>${Math.round(unlocked/ACH.length*100)}%</span></div></section><div class="ach-grid">${ACH.map(([n,d],i)=>{const m=achMeter(n,s),meta=ACH_META[n]||['award',n,d];return`<article class="ach-card ${m.done?'is-unlocked':'is-locked'}"><div class="ach-card-top"><span class="ach-icon-wrap">${ico(m.done?meta[0]:'lock')}</span><span class="ach-status">${m.done?'UNLOCKED':'LOCKED'}</span></div><div class="ach-card-body"><span class="ach-kicker">MILESTONE ${String(i+1).padStart(2,'0')}</span><h3>${esc(n)}</h3><p>${esc(meta[2]||d)}</p></div><div class="ach-card-foot">${m.done?`<span class="ach-earned">${ico('check')} Earned ${new Date(D.ach[n]).toLocaleDateString()}</span>`:`<div class="ach-progress-label"><span>Progress</span><b>${m.v}/${m.g}</b></div><div class="ach-progress"><i style="width:${m.pct}%"></i></div>`}</div><span class="ach-watermark">${ico(meta[0])}</span></article>`}).join('')}</div>`};
function freqPoly(ses){const f=Array(10).fill(0);ses.filter(x=>x.n).forEach(x=>f[Math.min(9,Math.floor(Math.round(x.c/x.n*100)/10))]++);const mx=Math.max(...f,1),Wd=560,H=230,l=38,r=14,t=16,b=40,iw=Wd-l-r,ih=H-t-b,X=i=>l+(i+1)/11*iw,Y=v=>t+ih-v/mx*ih,pts=[[-1,0],...f.map((v,i)=>[i,v]),[10,0]],line=pts.map(([i,v])=>X(i).toFixed(1)+','+Y(v).toFixed(1)).join(' ');if(!f.some(Boolean))return'<p class="sub">Complete a few sessions to see your accuracy distribution.</p>';return`<svg class="freq-poly" viewBox="0 0 ${Wd} ${H}" role="img" aria-label="Frequency polygon of session accuracy"><line x1="${l}" y1="${t+ih}" x2="${Wd-r}" y2="${t+ih}" class="fp-axis"/><line x1="${l}" y1="${t}" x2="${l}" y2="${t+ih}" class="fp-axis"/>${Array.from({length:mx+1},(_,v)=>mx>8&&v%Math.ceil(mx/5)?'':`<text x="${l-6}" y="${Y(v)+3}" text-anchor="end" class="fp-t">${v}</text>`).join('')}<polyline points="${line}" class="fp-line"/>${f.map((v,i)=>`<circle cx="${X(i).toFixed(1)}" cy="${Y(v).toFixed(1)}" r="4" class="fp-dot"><title>${i*10}–${i*10+10}%: ${v} session(s)</title></circle><text x="${X(i).toFixed(1)}" y="${t+ih+16}" text-anchor="middle" class="fp-t">${i*10+5}</text>`).join('')}<text x="${l+iw/2}" y="${H-4}" text-anchor="middle" class="fp-t">Session accuracy (class midpoint, %)</text></svg>`}
V.analytics=()=>{const s=st(),sessions=D.ses.filter(x=>x.mode!='mission'),tot=s.tc+s.ti,now=Date.now(),week=sessions.filter(x=>now-x.t<7*864e5),prev=sessions.filter(x=>now-x.t>=7*864e5&&now-x.t<14*864e5),weekCorrect=week.reduce((a,x)=>a+(x.c||0),0),prevCorrect=prev.reduce((a,x)=>a+(x.c||0),0),mins=D.ses.reduce((a,x)=>a+(x.ms||0),0),avgAcc=sessions.length?Math.round(sessions.reduce((a,x)=>a+(x.n?x.c/x.n*100:0),0)/sessions.filter(x=>x.n).length||0):0,best=sessions.reduce((b,x)=>!b||((x.n&&x.c/x.n)>(b.n?b.c/b.n:0))?x:b,null),attempted=W.filter(w=>{const p=D.p[w.id];return p&&(p.c+p.i)>0}).length,learnedPct=W.length?Math.round(s.learned/W.length*100):0,modeCounts={};sessions.forEach(x=>modeCounts[x.mode]=(modeCounts[x.mode]||0)+1);const topMode=Object.entries(modeCounts).sort((a,b)=>b[1]-a[1])[0],cats={};W.forEach(w=>{const k=w.cat||'Uncategorized';(cats[k]=cats[k]||[0,0,0]);cats[k][1]++;if(sOf(D.p[w.id])!='new')cats[k][0]++;if(sOf(D.p[w.id])=='mastered')cats[k][2]++});const catRows=Object.entries(cats).sort((a,b)=>b[1][0]-a[1][0]).slice(0,8);const activeLast7=new Set(week.map(x=>dayOf(x.t))).size,weekDelta=prevCorrect?Math.round((weekCorrect-prevCorrect)/prevCorrect*100):null;
 const dailyGoalDays=new Set(sessions.filter(x=>x.c>0).map(x=>dayOf(x.t))).size;
 return`<div class="page-heading"><div><span class="eyebrow">YOUR LEARNING DATA</span><h1>Analytics</h1><p class="sub">A clearer picture of your vocabulary growth, consistency and performance. <a class="text-link" href="#history">Exam history ↗</a></p></div></div><div class="analytics-hero card"><div><span class="eyebrow">TOTAL LEARNING XP</span><b>${s.xp.toLocaleString()}</b><small>${lvl(s.xp).name} · ${s.streak} day current streak</small></div><div class="analytics-hero-mark">${ico('chart-no-axes-combined')}</div></div>
 <div class="stats-grid analytics-stats">${stat(sessions.length,'Sessions completed')}${stat(s.tc,'Correct answers')}${stat(tot?Math.round(s.tc/tot*100)+'%':'–','Overall accuracy')}${stat(Math.round(mins/60000)+' min','Total study time')}${stat(attempted,'Words attempted')}${stat(learnedPct+'%','Collection learned')}${stat(s.days.size,'Active days')}${stat(s.cnt.mastered,'Words mastered')}</div>
 <div class="analytics-columns"><section><div class="section-head"><div><span class="eyebrow">CONSISTENCY</span><h2>XP activity · last 7 days</h2></div></div><div class="card chart-card">${chart(last7())}<p class="data-note">Your daily XP trend, based on recorded sessions.</p></div></section><section><div class="section-head"><div><span class="eyebrow">PERFORMANCE</span><h2>Answer accuracy</h2></div></div><div class="card analytics-highlight"><div class="accuracy-donut" style="--value:${tot?Math.round(s.tc/tot*100):0}%"><span>${tot?Math.round(s.tc/tot*100):0}%</span></div><div><b>${s.tc.toLocaleString()} correct</b><small>${s.ti.toLocaleString()} incorrect answers</small><small>${avgAcc}% average session accuracy</small></div></div></section></div>
 <h2>Learning overview</h2><div class="grid analytics-secondary">${stat(week.length,'Sessions this week')}${stat(weekCorrect,'Correct this week')}${stat(activeLast7+'/7','Days active this week')}${stat(best&&best.n?Math.round(best.c/best.n*100)+'%':'–','Best session accuracy')}${stat(topMode?MODE_NAME[topMode[0]]||topMode[0]:'–','Most-used activity')}${stat(s.r,'Revision answers')}</div>${weekDelta===null?'<p class="data-note">Weekly comparison will appear after you have activity across two weeks.</p>':`<p class="data-note">Correct answers this week: ${weekDelta>=0?'+':''}${weekDelta}% compared with the previous 7 days (${prevCorrect} then → ${weekCorrect} now).</p>`}
 <div class="analytics-columns"><section><h2>Mastery distribution</h2><div class="card">${chart(Object.entries(s.cnt).map(([k,v])=>[k,v]))}</div></section><section><h2>Progress by difficulty</h2><div class="card difficulty-analytics">${DIFFICULTIES.map(l=>{const a=W.filter(w=>Number(w.difficulty)===l.id),done=a.filter(w=>sOf(D.p[w.id])!='new').length,pct=a.length?Math.round(done/a.length*100):0;return`<div class="difficulty-row"><div><b>${l.name}</b><span>${done}/${a.length} words</span></div><div class="ach-progress"><i style="width:${pct}%"></i></div><small>${pct}%</small></div>`}).join('')}</div></section></div>
 <h2>Frequency polygon · session accuracy</h2><div class="card chart-card">${freqPoly(sessions)}<p class="data-note">How many sessions fell in each accuracy band (10% classes). The polygon joins class midpoints and closes at zero on both ends.</p></div>
 <h2>Activity calendar · last 28 days</h2><div class="card activity-calendar"><div class="calendar-grid">${Array.from({length:28},(_,i)=>{const d=new Date();d.setDate(d.getDate()-27+i);const key=dayOf(d),a=s.days.has(key),count=sessions.filter(x=>dayOf(x.t)==key).length;return`<span class="calendar-cell ${a?'active':''}" title="${key}: ${count} session(s)"></span>`}).join('')}</div><div class="calendar-legend"><span>Less</span><i></i><i></i><i></i><i></i><span>More</span></div></div>`};
V.profile=()=>{const s=st(),l=lvl(s.xp);return`<h1>Profile</h1><section class="card profile-editor"><div class="profile-edit-head"><img id="profile-avatar" class="profile-avatar" src="${D.profilePhoto||'assets/photos/araf.jpg'}" onerror="this.onerror=null;this.src='assets/photos/araf.svg'" alt="Profile photo"><div><b>Personal details</b><p class="sub">নিজের পরিচয় ও ছবি যোগ করে প্রোফাইল সাজাও।</p><label class="btn profile-upload">Upload photo<input type="file" accept="image/*" hidden onchange="uploadProfilePhoto(this.files[0])"></label></div></div><div class="profile-fields"><label>নাম<input value="${esc(D.name||'Learner')}" placeholder="তোমার নাম" onchange="saveProfileField('name',this.value)"></label><label>স্কুল / কলেজ<input value="${esc(D.institution||'')}" placeholder="School or College" onchange="saveProfileField('institution',this.value)"></label><label>ক্লাস / স্তর<input value="${esc(D.klass||'')}" placeholder="Class / Academic level" onchange="saveProfileField('klass',this.value)"></label><label>অবস্থান<input value="${esc(D.location||'')}" placeholder="Location" onchange="saveProfileField('location',this.value)"></label><label>শেখার লক্ষ্য<input value="${esc(D.learnGoal||'')}" placeholder="Learning goal" onchange="saveProfileField('learnGoal',this.value)"></label><label>প্রিয় শব্দ-ক্যাটাগরি<select onchange="saveProfileField('favCat',this.value)"><option value="">—</option>${[...new Set(W.map(w=>w.cat).filter(Boolean))].sort().map(c=>`<option ${D.favCat==c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label class="profile-bio">সংক্ষিপ্ত পরিচয়<textarea placeholder="Short bio" onchange="saveProfileField('bio',this.value)">${esc(D.bio||'')}</textarea></label></div><p class="sub">ছবি ও তথ্য এই ব্রাউজারেই সংরক্ষিত থাকবে। ছবি সর্বোচ্চ ২ MB রাখো।</p></section><div class="grid">${stat('Lv '+(l.i+1),l.name)}${stat(s.xp,'Total XP')}${stat(s.streak,'Current streak')}${stat(s.cnt.mastered,'Mastered')}${stat(Object.keys(D.ach).length,'Badges')}</div><section class="creator-mini">${photo('araf','Creator portrait')}<div><b>${CREATOR.name}</b><small>${CREATOR.role} of VocabHub</small><small>${CREATOR.title}</small></div><a href="#about">About ↗</a></section><p class="sub" style="margin-top:14px">Your progress is saved in this browser on this device only. It is not shared with other users or devices — use Settings → Backup to move it.</p>`};
V.settings=()=>`<div class="page-heading"><div><span class="eyebrow">MAKE IT YOUR SPACE</span><h1>Settings</h1><p class="sub">Choose how VocabHub looks and set a learning target.</p></div></div><section class="settings-section"><div class="section-head compact"><div><span class="eyebrow">APPEARANCE</span><h2>Choose your atmosphere</h2></div><span class="soft-pill">2 themes</span></div><div class="theme-picker">${[['midnight','Dark','Black canvas · red accents'],['paper','Light','Clean white · red & black']].map(([id,n,d])=>`<button class="theme-choice ${activeTheme()==id?'selected':''}" onclick="D.theme='${id}';save();theme();render()"><span class="theme-preview preview-${id}"><i></i><i></i><i></i><b></b></span><span class="theme-choice-text"><b>${n}</b><small>${d}</small></span><span class="theme-check">${activeTheme()==id?'✓':'○'}</span></button>`).join('')}</div></section><section class="settings-section card settings-goal"><div><span class="eyebrow">DAILY ROUTINE</span><h2>Daily learning target</h2><p class="sub">Set the number of correct answers you want to reach each day.</p></div><label class="goal-input"><input type="number" min="5" max="200" value="${D.goal}" onchange="D.goal=Math.max(5,Math.min(200,+this.value||20));save();render()"><span>correct answers / day</span></label></section>
 <h2>Backup & restore</h2><div class="card settings-backup"><p class="sub">Your vocabulary and learning progress are stored in this browser on this device. Download a backup before clearing browser data.</p><div class="row"><button class="btn pri" onclick="download('vocabhub-backup-'+dayOf(Date.now())+'.json',JSON.stringify(D),'application/json')">↓ Download backup</button><label class="btn">Restore backup<input type="file" accept=".json" hidden onchange="restore(this.files[0])"></label><button class="btn" onclick="if(confirm('Delete ALL progress (vocabulary kept)?')){D.p={};D.ses=[];D.ach={};D.claims={};D.fav={};save();render()}">Reset progress</button></div></div>`;
function restore(f){if(!f)return;f.text().then(t=>{try{const j=JSON.parse(t);if(!j.p||!j.ses)throw 0;if(!confirm('Replace current data with this backup?'))return;D=Object.assign(D,j);W=D.words||[];save();theme();render();toast('Backup restored')}catch(e){toast('Invalid backup file')}})}
V.admin=()=>`<h1>Admin</h1><p class="sub">Manage your vocabulary locally. (Local-only: no server, so there is no login; anyone using this browser can edit.)</p>
 <div class="card"><b>Import</b><p class="sub">Paste lines like <code>Rightful: বৈধ / ন্যায্য</code>, or CSV (header: word,bengali_meaning,part_of_speech,synonyms,antonyms,example,example_translation,difficulty,category), or JSON. Duplicate words are merged, not repeated.</p><textarea id="imp"></textarea><div class="row"><button class="btn" onclick="imp(1)">Preview</button><button class="btn pri" onclick="imp(0)">Import</button><label class="btn">From file<input type="file" accept=".txt,.csv,.json" hidden onchange="this.files[0].text().then(t=>{$('#imp').value=t})"></label></div><div id="impr" class="sub"></div></div>
 <h2>Add / edit one word</h2><div class="card"><div class="row">${[['en','English word'],['bn','Bengali meaning'],['pos','Part of speech'],['syn','Synonyms (;)'],['ant','Antonyms (;)'],['ex','Example'],['ext','Example translation'],['diff','Difficulty'],['cat','Category']].map(([k,p])=>`<input id="f_${k}" placeholder="${p}">`).join('')}<button class="btn pri" onclick="addOne()">Save word</button></div><p class="sub">Using an existing English word replaces its meaning with what you enter.</p></div>
 <h2>Difficulty classification</h2><div class="card"><p class="sub">Review and edit the level of each existing word. Original collection labels are preserved.</p><div class="row"><select id="classLevel"><option value="1">Beginner</option><option value="2">Elementary</option><option value="3" selected>Intermediate</option><option value="4">Advanced</option><option value="5">Expert</option></select><input id="classSearch" placeholder="Find an existing word"><button class="btn" onclick="findClassWords()">Find</button></div><div id="classResults"></div></div><h2>Export / maintenance</h2><div class="row"><button class="btn" onclick="download('vocabulary.json',JSON.stringify({words:W},null,1),'application/json')">Export JSON</button><button class="btn" onclick="download('vocabulary.csv',toCSV(),'text/csv')">Export CSV</button><button class="btn" onclick="reload()">Sync latest GitHub vocabulary</button></div>
 <h2>Words (${W.length})</h2><div class="card">${W.slice(-100).reverse().map(w=>{const i=W.indexOf(w);return`<div class="row" style="margin:4px 0">${esc(w.en)} — <span class="bn">${esc(w.bn)}</span> <button class="btn" onclick="del(${i})">Delete</button></div>`}).join('')||'Empty'}${W.length>100?'<p class="sub">Showing latest 100</p>':''}</div>`;
function findClassWords(){const q=$('#classSearch').value.trim().toLowerCase(),a=W.filter(w=>!q||w.en.toLowerCase().includes(q)).slice(0,40);$('#classResults').innerHTML=a.map(w=>`<div class="classify-row"><span><b>${esc(w.en)}</b><small>${esc(w.bn)}</small></span><select onchange="setWordDifficulty('${esc(w.id)}',this.value)">${DIFFICULTIES.map(l=>`<option value="${l.id}" ${Number(w.difficulty)===l.id?'selected':''}>${l.name}</option>`).join('')}</select></div>`).join('')||'<p class="sub">No matching words.</p>';}
function setWordDifficulty(id,val){const w=W.find(x=>x.id===id);if(!w)return;w.difficulty=Number(val);w.level=DIFFICULTIES.find(x=>x.id===Number(val)).name;w.classificationStatus='reviewed';save();toast(w.en+' → '+w.level);if($('#classResults'))findClassWords();}
function imp(dry){const r=doImport($('#imp').value,dry);$('#impr').textContent=r.err||`${dry?'Preview: ':'Done: '}${r.total} rows → ${r.added} new, ${r.merged} merged with existing, ${r.skipped} skipped`;if(!dry&&!r.err){toast('Imported '+r.added+' new words');render()}}
function addOne(){const g=k=>$('#f_'+k).value.trim(),o={en:g('en'),bn:g('bn'),pos:g('pos'),syn:lst(g('syn')),ant:lst(g('ant')),ex:g('ex'),ext:g('ext'),diff:g('diff'),cat:g('cat'),rep:1};if(!o.en||!o.bn)return toast('English word and Bengali meaning are required');addW(W,o);{const nw=W.find(x=>x.en===o.en);if(nw&&nw.difficulty==null){nw.difficulty=3;nw.level='Intermediate'}}save();toast('Saved');render()}
function del(i){if(confirm('Delete "'+W[i].en+'"?')){delete D.p[W[i].id];W.splice(i,1);save();render()}}
const REMOTE_VOCAB_URL='https://raw.githubusercontent.com/saimumaraf2009-gif/vocab-hub/main/vocabulary.json';
async function syncRemoteVocabulary({silent=false}={}){
 try{
  const response=await fetch(REMOTE_VOCAB_URL,{cache:'no-store'});
  if(!response.ok)throw new Error('HTTP '+response.status);
  const payload=await response.json(),remote=Array.isArray(payload)?payload:payload.words;
  if(!Array.isArray(remote)||!remote.length)throw new Error('Invalid vocabulary JSON');
  const localById=new Map(W.map(w=>[w.id||nid(w.en||''),w]));
  const remoteIds=new Set();
  const merged=remote.map(source=>{
   const id=source.id||nid(source.en||'');if(!id||!source.en)return null;remoteIds.add(id);
   const local=localById.get(id)||{};
   // GitHub JSON is authoritative for core vocabulary fields. Keep app-side
   // enrichment/custom metadata that is not supplied by the remote dataset.
   const extra={};['ipa','ipaDialect','ipaSource','sources','enrichmentStatus','added'].forEach(k=>{if(local[k]!=null)extra[k]=local[k]});
   return {...local,...source,...extra,id};
  }).filter(Boolean);
  // Keep words added locally by the learner; remote entries remain primary.
  W.forEach(w=>{const id=w.id||nid(w.en||'');if(id&&!remoteIds.has(id))merged.push(w)});
  W=merged;
  W.forEach(w=>{if(w.difficulty==null||isNaN(Number(w.difficulty))){w.difficulty=3;w.level='Intermediate';w.classificationStatus=w.classificationStatus||'auto'}});
  save();render();
  if(!silent)toast('GitHub থেকে '+remote.length+'টি শব্দ লোড হয়েছে');
  return true;
 }catch(error){if(!silent)toast('GitHub database লোড হয়নি; saved/offline vocabulary ব্যবহার হচ্ছে।');return false}
}
function reload(){if(!confirm('GitHub-এর সর্বশেষ vocabulary দিয়ে local word list আপডেট করবে? Learning progress অপরিবর্তিত থাকবে।'))return;syncRemoteVocabulary()}


/* ---------- exam history ---------- */
const HF={m:'',n:15};
const fmtDur=ms=>{const t=Math.round(ms/1000);return t>=60?Math.floor(t/60)+'m '+(t%60)+'s':t+'s'};
const sesAcc=x=>x.n?Math.round(x.c/x.n*100):0;
V.history=()=>{const all=D.ses.filter(x=>x.mode!='mission'&&x.n>0),tot=all.length,avg=tot?Math.round(all.reduce((a,x)=>a+sesAcc(x),0)/tot):0,best=all.filter(x=>x.n>=5).reduce((b,x)=>Math.max(b,sesAcc(x)),0),time=all.reduce((a,x)=>a+(x.ms||0),0),wk=all.filter(x=>Date.now()-x.t<7*864e5).length,recent=all.slice(-10).map(x=>[new Date(x.t).toLocaleDateString('en',{day:'numeric',month:'short'}),sesAcc(x)]),modes=[...new Set(all.map(x=>x.mode))];
 return`<div class="page-heading"><div><span class="eyebrow">EVERY SESSION YOU HAVE COMPLETED</span><h1>Exam history</h1><p class="sub">কতবার পরীক্ষা ও গেমে অংশ নিয়েছ এবং কেমন ফল করেছ — সব এখানে জমা থাকবে।</p></div><span class="count-tile"><b>${tot}</b><small>EXAMS</small></span></div>
 <div class="grid">${stat(tot,'Total exams')}${stat(tot?avg+'%':'–','Average score')}${stat(best?best+'%':'–','Best score')}${stat(wk,'This week')}${stat(fmtDur(time),'Time spent')}</div>
 ${recent.length>1?`<h2>Score trend · last ${recent.length}</h2><div class="card chart-card">${chart(recent)}<p class="data-note">Accuracy (%) of your most recent sessions.</p></div>`:''}
 <div class="section-head"><div><span class="eyebrow">ALL SESSIONS</span><h2>Past exams</h2></div>${modes.length>1?`<select aria-label="Filter by exam type" onchange="HF.m=this.value;HF.n=15;drawHist()">${['',...modes].map(m=>`<option value="${m}" ${HF.m==m?'selected':''}>${m?MODE_NAME[m]||m:'All types'}</option>`).join('')}</select>`:''}</div>
 <div id="hist-list" class="hist-list"></div>`};
function histRow(x){const a=sesAcc(x),d=new Date(x.t),lv=DIFFICULTIES.find(l=>l.id===x.lv),bad=(x.bad||[]).map(id=>W.find(w=>w.id===id)).filter(Boolean);
 return`<article class="hist-row"><div class="hist-top"><span class="mode-icon">${ico(x.mode)}</span><div class="hist-main"><b>${MODE_NAME[x.mode]||x.mode}</b><small>${d.toLocaleDateString('en',{day:'numeric',month:'short',year:'numeric'})} · ${d.toLocaleTimeString('en',{hour:'numeric',minute:'2-digit'})}${lv?' · '+lv.name:''}</small></div><div class="hist-score"><b>${x.c}/${x.n}</b><small>${a}%</small></div></div><div class="bar"><i style="width:${a}%"></i></div><div class="hist-meta"><span class="chip">+${x.xp||0} XP</span><span class="chip">${fmtDur(x.ms||0)}</span>${x.r?`<span class="chip">${x.r} revised</span>`:''}</div>${bad.length?`<details class="hist-detail"><summary>Review ${bad.length} mistake${bad.length>1?'s':''}</summary>${bad.map(w=>`<div>${esc(w.en)} — <span class="bn">${esc(w.bn)}</span></div>`).join('')}</details>`:''}</article>`}
function drawHist(){const el=$('#hist-list');if(!el)return;const rows=D.ses.filter(x=>x.mode!='mission'&&x.n>0&&(!HF.m||x.mode==HF.m)).sort((a,b)=>b.t-a.t);
 el.innerHTML=rows.length?rows.slice(0,HF.n).map(histRow).join('')+(rows.length>HF.n?`<button class="btn" onclick="HF.n+=15;drawHist()">Show more (${rows.length-HF.n})</button>`:''):`<div class="card empty"><h2>No exams yet</h2><p>Finish a practice or game session and it will be listed here.</p></div>`}
/* ---------- mistakes ---------- */
let MT='active';
const mistWords=f=>W.filter(w=>D.mist[w.id]&&f(D.mist[w.id]));
V.mistakes=()=>{const act=mistWords(m=>!m.fixed),fx=mistWords(m=>m.fixed),tot=Object.values(D.mist).reduce((a,m)=>a+m.w,0),ex=D.ses.filter(x=>x.mode=='mistakes').length,cnt=[{v:5,t:'5 questions'},{v:10,t:'10 questions'},{v:20,t:'20 questions'},{v:999,t:'All weak words'}];
 return`<div class="page-heading"><div><span class="eyebrow">LEARN FROM YOUR MISTAKES</span><h1>Mistakes</h1><p class="sub">যেসব শব্দে ভুল হয়েছে সেগুলো এখানে জমা হয়। একটি শব্দ পরপর ৩ বার সঠিক হলে "Recovered" হয়ে যায়।</p></div><span class="count-tile"><b>${act.length}</b><small>TO FIX</small></span></div>
 <div class="grid">${stat(act.length,'Words to fix')}${stat(fx.length,'Recovered')}${stat(tot,'Wrong answers')}${stat(ex,'Mistake exams')}</div>
 <section class="card exam-card"><div class="exam-copy"><span class="eyebrow">MISTAKES EXAM</span><h2>Test yourself on weak words</h2><p class="sub">শুধু ভুল করা শব্দ থেকে মিক্সড প্রশ্ন — MCQ, শব্দ সাজানো, বাক্য সাজানো, Odd one out ইত্যাদি।</p></div><div class="exam-actions">${ddHTML('mx-count',cnt,10)}<button class="btn pri" onclick="startMistakeExam()" ${act.length?'':'disabled'}>Start exam →</button><button class="btn" onclick="start('boss')">Boss battle</button></div></section>
 <div id="mist-body"></div>`};
const setMT=k=>{MT=k;drawMist()};
function drawMist(){const el=$('#mist-body');if(!el)return;const act=mistWords(m=>!m.fixed).sort((a,b)=>D.mist[b.id].w-D.mist[a.id].w||D.mist[b.id].t-D.mist[a.id].t),fx=mistWords(m=>m.fixed).sort((a,b)=>D.mist[b.id].fixed-D.mist[a.id].fixed),ex=D.ses.filter(x=>x.mode=='mistakes'||x.mode=='boss').sort((a,b)=>b.t-a.t);
 const dt=t=>new Date(t).toLocaleDateString('en',{day:'numeric',month:'short'});
 const row=(w,m,fixed)=>`<article class="mist-row"><button class="mist-word" onclick="openWord('${w.id}')"><b>${esc(w.en)}</b><small class="bn">${esc(short(w.bn))}</small></button><div class="mist-meta"><span class="chip">${m.w} wrong</span><span class="chip">${fixed?'Recovered '+dt(m.fixed):'Last '+dt(m.t)}</span>${fixed?'':`<span class="mist-dots" title="${m.ok}/3 correct in a row">${[0,1,2].map(i=>`<i class="${i<m.ok?'on':''}"></i>`).join('')}</span>`}</div></article>`;
 const tabs=[['active','Needs practice',act.length],['fixed','Recovered',fx.length],['exams','Exam results',ex.length]];
 let body;
 if(MT=='active')body=act.length?act.map(w=>row(w,D.mist[w.id],0)).join(''):`<div class="card empty"><h2>Nothing to fix</h2><p>Wrong answers from practice and games will appear here.</p></div>`;
 else if(MT=='fixed')body=fx.length?fx.map(w=>row(w,D.mist[w.id],1)).join(''):`<div class="card empty"><h2>No recovered words yet</h2><p>Answer a weak word correctly 3 times in a row and it moves here.</p></div>`;
 else body=ex.length?ex.map(histRow).join(''):`<div class="card empty"><h2>No mistake exams yet</h2><p>Start a Mistakes exam or Boss battle above.</p></div>`;
 el.innerHTML=`<div class="tabs" role="tablist">${tabs.map(([k,n,c])=>`<button class="tab ${MT==k?'on':''}" role="tab" onclick="setMT('${k}')">${n}<span>${c}</span></button>`).join('')}</div><div class="hist-list">${body}</div>`}
V.levels=()=>`<div class="page-heading"><div><span class="eyebrow">CHOOSE YOUR CHALLENGE</span><h1>Difficulty journey</h1><p class="sub">All five levels are open. Choose any level and practise with any game.</p></div><span class="count-tile"><b>${W.length}</b><small>WORDS</small></span></div><div class="level-journey-grid">${DIFFICULTIES.map(l=>{const a=wordsAtLevel(l.id),mastered=a.filter(w=>sOf(D.p[w.id])==='mastered').length;return`<article class="level-journey-card level-${l.id}"><div class="level-card-top"><span class="level-number">0${l.id}</span><span class="level-difficulty">${l.tag}</span></div><h2>${l.name}</h2><p>${l.desc}</p><div class="level-count-row"><b>${a.length}</b><span>words</span><span class="level-mastered">${mastered} mastered</span></div><div class="bar"><i style="width:${a.length?mastered/a.length*100:0}%"></i></div><div class="level-card-actions"><button class="btn pri" onclick="go('practice');D.gameLevels.mcq=${l.id};save()">Practise this level ↗</button><button class="btn" onclick="openLevelWords(${l.id})">View words</button></div></article>`}).join('')}</div><p class="sub level-note">Difficulty is editorially assigned to the existing vocabulary only. The original collection/category field remains unchanged.</p>`;
function openLevelWords(id){L.q='';L.st='';L.cat='';L.fav=false;D.libraryDifficulty=id;go('lib')}
V.about=()=>`<div class="page-heading"><div><span class="eyebrow">THE STORY BEHIND THE STUDIO</span><h1>About VocabHub</h1><p class="sub">A focused space to build a stronger English vocabulary.</p></div></div><section class="creator-card"><div class="creator-photo-wrap">${photo('araf','Moshiur Rahman Araf — creator portrait')}</div><div class="creator-copy"><span class="eyebrow">FOUNDER & CREATOR</span><h2>${CREATOR.name}</h2><p class="creator-title">${CREATOR.title}</p><p>Created with a simple goal: make vocabulary learning more structured, engaging and memorable.</p><div class="creator-signature">CREATED BY MOSHIUR RAHMAN ARAF</div></div></section><section class="creator-card powered-card"><div class="creator-photo-wrap">${photo('shahed',PARTNER.by+' — portrait')}</div><div class="creator-copy"><span class="eyebrow">POWERED BY</span><img class="hub-logo-about" src="assets/hub-logo.png" alt="Shahed's English Hub logo"><h2>${PARTNER.hub}</h2><p class="powered-by-line">by <b>${PARTNER.by}</b></p><p>${PARTNER.dept}</p><div class="creator-signature">POWERED BY SHAHED'S ENGLISH HUB</div></div></section><section class="brand-showcase"><div class="brand-logo-large"><img src="assets/logo.png" alt="VocabHub logo"><div><strong>VocabHub</strong><small>YOUR PERSONAL VOCABULARY STUDIO</small></div></div><div><span class="eyebrow">OUR APPROACH</span><h2>Learn · Practise · Remember</h2><p class="sub">Five open difficulty levels, a shared game arena, smart revision and your own vocabulary library — built around the words already included in this edition.</p></div></section>`;

V.play=()=>{if(!S)return'<p>No session.</p>';if(S.fin){const a=T(S.mode)?S.att:S.n;return`<h1>Results</h1><div class="grid">${stat(S.c+' / '+a,'Correct')}${stat(a?Math.round(S.c/a*100)+'%':'–','Accuracy')}${stat('+'+S.xp,'XP')}${stat(Math.round((Date.now()-S.t0)/1000)+'s','Time')}${S.lad?stat(S.lad.peak,'Peak level'):''}${S.mode=='boss'?stat(S.lives>0?'Defeated':'Lost','Boss'):''}${S.rec&&S.rec.length?stat(S.rec.length,'Words recovered'):''}</div>${S.bad.length?`<h2>Review these</h2><div class="card">${[...new Set(S.bad)].map(w=>`<div>${esc(w.en)} — <span class="bn">${esc(w.bn)}</span></div>`).join('')}</div>`:''}${progressMini()}<div class="row"><button class="btn pri" onclick="start('${S.mode}',{n:${S.n0||S.n},dur:${S.dur||0}})">Play again</button><a class="btn" href="#history" style="text-decoration:none">Exam history</a><a class="btn" href="#${GAME_MODES.includes(S.mode)?'arcade':S.mode=='mistakes'?'mistakes':'practice'}" style="text-decoration:none">Back</a></div>`}
 if(S.mode=='mem')return memHTML();
 if(S.mode=='match'){return`<h1>Word Matching</h1><p class="sub">Tap an English word, then its meaning. ${S.done.size}/${S.ws.length}</p><div class="m"><div>${S.L.map((w,i)=>`<button class="btn opt ${S.done.has(w.id)?'dn':''} ${S.sel&&S.sel.id==w.id?'sel':''}" onclick="matchClick('L',${i})">${esc(w.en)}</button>`).join('')}</div><div>${S.R.map((w,i)=>`<button class="btn opt bn ${S.done.has(w.id)?'dn':''}" onclick="matchClick('R',${i})">${esc(short(w.bn))}</button>`).join('')}</div></div>`}
 if(S.mode=='flash'){const w=S.ws[S.i];return`<h1>Flashcard Recall</h1><p class="sub">${S.i+1} / ${S.ws.length}</p><div class="card"><div class="big">${esc(w.en)}</div>${S.rev?`<div class="big bn" style="font-size:24px">${esc(w.bn)}</div>${w.ex?'<p class="sub">'+esc(w.ex)+'</p>':''}<div class="row"><button class="btn pri" onclick="flashAns(1)">I know this</button><button class="btn" onclick="flashAns(0)">Need more practice</button></div>`:'<div class="row"><button class="btn pri" onclick="S.rev=1;render()">Reveal</button></div>'}</div>`}
 const q=S.qs[S.i];return`<h1>${T(S.mode)?(S.mode=='tf'?'True / False Blitz':'Speed Challenge')+' · <span id="tm">'+Math.max(0,Math.ceil((S.end-Date.now())/1000))+'s</span>':'Question '+(S.i+1)+' / '+(S.n||S.qs.length)}</h1><p class="sub">${esc(q.sub||'')} · ${S.c} correct${hudExtra()}</p>${!T(S.mode)?`<div class="bar"><i style="width:${S.i/(S.n||S.qs.length)*100}%"></i></div>`:''}<div class="card ${q.t=='tf'?'tf-card':''}"><div class="big ${q.bn?'bn':''} ${q.long?'long':''}">${esc(q.prompt)}</div>${q.letters?scrHTML(q):q.t=='hang'?hgHTML(q):q.opts?q.opts.map((o,i)=>`<button class="btn opt ${/[\u0980-\u09FF]/.test(o)?'bn':''}" onclick="pickOpt(${i})">${esc(o)}</button>`).join(''):`<div class="row"><input id="in" autocomplete="off" autofocus placeholder="Type your answer" onkeydown="if(event.key=='Enter')submitTyped()"><button class="btn pri" onclick="submitTyped()">Check</button><button class="btn" onclick="hint()">Hint</button></div><p class="sub" id="hint"></p>`}<div id="fb"></div></div>`};
const PAGES=[['dash','Dashboard','dash'],['levels','Levels','levels'],['lib','Library','lib'],['practice','Practice','practice'],['arcade','Arcade','arcade'],['revision','Revision','revision'],['mistakes','Mistakes','mistakes'],['missions','Missions','missions'],['achievements','Achievements','achievements'],['analytics','Analytics','analytics'],['history','History','history'],['profile','Profile','profile'],['settings','Settings','settings'],['admin','Word manager','admin'],['about','About VocabHub','about']];
const PRIMARY=['dash','levels','lib','practice','arcade'];
const MOBILE_MORE=['revision','mistakes','missions','achievements','analytics','history','profile','settings','admin','about'];
const pageLink=([k,n,ic],v,extra='')=>`<a href="#${k}" class="${k==v?'on':''} ${extra}" aria-label="${n}"><span class="nav-ic">${ico(ic)}</span><span>${n}</span></a>`;
function topbar(v){const pg=PAGES.find(x=>x[0]===v)||PAGES[0],s=st();return`<header class="topbar"><div class="topbar-context"><span class="topbar-kicker"><img class="topbar-brand-icon" src="assets/logo.png" alt=""> VOCABHUB / LEARNING SPACE</span><b>${pg[1]}</b></div><div class="topbar-actions"><a class="hub-chip" href="#about" title="Powered by Shahed's English Hub"><img src="assets/hub-logo.png" alt="Shahed's English Hub"></a><span class="xp-chip">✦ ${s.xp} XP</span><button class="theme-toggle" onclick="cycleTheme()" aria-label="Change theme" title="Change theme"><span>${activeTheme()==='midnight'?'☾':'☼'}</span><small>${activeTheme()==='midnight'?'Dark':'Light'}</small></button></div></header>`}
const go=r=>{location.hash==='#'+r?render():location.hash=r};
function render(){const r=location.hash.slice(1)||'dash',v=V[r]?r:'dash';if(v!='play'&&S&&S.iv&&!S.fin){clearInterval(S.iv);S.iv=0}$('#nav').classList.remove('more-open')
 const desktop=[...PAGES.filter(p=>['dash','levels','lib','practice','arcade'].includes(p[0])),...PAGES.filter(p=>['revision','mistakes','missions','achievements','analytics','history','profile','settings','admin'].includes(p[0]))];
 $('#nav').innerHTML=`<div class="side-brand"><img src="assets/logo.png" alt=""><span>Vocab<span>Hub</span><small>LEARN · PRACTICE · REMEMBER</small></span></div><div class="sidebar-scroll"><div class="nav-group"><small>WORKSPACE</small>${desktop.slice(0,5).map(p=>pageLink(p,v)).join('')}</div><div class="nav-group"><small>YOUR PROGRESS</small>${desktop.slice(5).map(p=>pageLink(p,v)).join('')}</div><div class="nav-group"><small>TOOLS</small>${pageLink(PAGES[PAGES.length-1],v)}</div></div><div class="sidebar-footer"><a class="powered-mini creator-side" href="#about">${photo('araf',CREATOR.name,'creator-side-img')}<div><small>${CREATOR.role.toUpperCase()}</small><b>${CREATOR.name}</b><small>${CREATOR.title}</small></div></a><a class="powered-mini" href="#about"><img class="hub-logo-mini" src="assets/hub-logo.png" alt="Shahed's English Hub"><div><small>POWERED BY</small><b>${PARTNER.hub}</b><small>by ${PARTNER.by}</small></div></a></div><div class="mobile-more">${PAGES.filter(p=>MOBILE_MORE.includes(p[0])).map(p=>pageLink(p,v)).join('')}</div><nav class="mobile-dock">${PAGES.filter(p=>PRIMARY.includes(p[0])).map(p=>pageLink(p,v)).join('')}<button class="more-trigger ${MOBILE_MORE.includes(v)?'on':''}" onclick="toggleMore()"><span class="nav-ic">···</span><span>More</span></button></nav>`;
 $('#main').innerHTML=topbar(v)+`<div class="page-enter">${V[v]()}</div><footer class="site-credit"><span>VocabHub</span><a class="credit-creator" href="#about"><span><b>${CREATOR.name}</b></span></a><a class="powered-badge" href="#about"><img class="hub-logo-foot" src="assets/hub-logo.png" alt="Shahed's English Hub"><span>Powered by <b>${PARTNER.hub}</b><small>by ${PARTNER.by} · ${PARTNER.dept}</small></span></a></footer>`;if(v=='lib'&&W.length)drawLib();if(v=='history')drawHist();if(v=='mistakes')drawMist();if(v=='play'&&S&&T(S.mode)&&!S.fin&&!S.iv)finish();if(v=='lib'&&L.q){const q=$('#q');if(q)q.value=L.q}if(v=='play'&&S&&T(S.mode)&&!S.fin)tick();scrollTo(0,0)}
addEventListener('hashchange',render);matchMedia('(prefers-color-scheme:dark)').addEventListener('change',theme);

// Difficulty-aware wrapper: every game receives its own saved level selector.
const startUnfiltered=start;
start=function(mode,o={}){
 if(['mistakes','boss','daily','ladder'].includes(mode))return startSpecial(mode,o);
 clearInterval(S&&S.iv);S=null;
 const chosen=Number(o.level||D.gameLevels[mode]||3),pool=wordsAtLevel(chosen);
 if(pool.length<4){toast('এই Level-এ অন্তত ৪টি শব্দ দরকার। অন্য Level বেছে নাও।');return}
 const original=W;W=pool;
 try{startUnfiltered(mode,{...o,level:chosen});if(S)S.level=chosen;}finally{W=original;}
 if(['fill','syn','odd','sent'].includes(mode)&&!(S&&S.qs&&S.qs.length)){document.querySelectorAll('#toasts .toast').forEach(t=>t.remove());startUnfiltered(mode,{...o});if(S&&S.qs&&S.qs.length){S.level=0;toast('এই Level-এ এই গেমের জন্য উদাহরণ/সমার্থক শব্দ নেই — সব Level থেকে প্রশ্ন নেওয়া হয়েছে।')}}
};

theme();
/* Local-first startup: render saved/bundled data immediately (including file://),
   then refresh the primary vocabulary from the user's GitHub JSON. Learning
   progress lives in D.p / sessions / achievements and is never reset here. */
W=Array.isArray(D.words)?D.words:[];
BUNDLED_WORDS.forEach(w=>{addW(W,w);const existing=W.find(x=>x.id===w.id);if(existing&&existing.difficulty==null){existing.difficulty=w.difficulty;existing.level=w.level;existing.classificationStatus=w.classificationStatus||'reviewed';}});
W.forEach(w=>{if(w.difficulty==null||isNaN(Number(w.difficulty))){w.difficulty=3;w.level='Intermediate';w.classificationStatus=w.classificationStatus||'auto'}});
save();
render();
// GitHub Pages / localhost can fetch the canonical JSON; offline and file:// use fallback.
syncRemoteVocabulary({silent:true});


