let IBA=(()=>{try{return JSON.parse(localStorage.getItem(IBA_STORE)||'{}')}catch(e){return {}}})();
IBA.questions=Array.isArray(IBA.questions)?IBA.questions:IBA_SEED;
IBA.words=Array.isArray(IBA.words)?IBA.words:[];
IBA.progress=IBA.progress||{}; IBA.mistakes=IBA.mistakes||{}; IBA.history=IBA.history||[];
IBA.cycles=IBA.cycles||{}; IBA.importLog=IBA.importLog||[];
let IBA_TAB='dashboard',IBA_SESSION=null;
function ibaSave(){try{localStorage.setItem(IBA_STORE,JSON.stringify(IBA))}catch(e){toast('IBA data storage is full. Export your IBA backup before importing more.')}} 
function ibaEsc(s){return esc(s)}
function ibaNorm(s){return String(s||'').toLowerCase().replace(/[^a-z'-]/g,'').trim()}
function ibaType(q){const s=(q.question||'').toLowerCase();if(/synonym/.test(s))return'Synonym';if(/antonym|opposite/.test(s))return'Antonym';if(/fill in the blank|fill in the gap|blank/.test(s))return'Fill in the blanks';if(/erroneous part|error/.test(s))return'Error identification';if(/passage|according to|inference|main point|primary purpose/.test(s))return'Reading comprehension';if(/relationship|pair of words|analogy/.test(s))return'Analogy';return'Mixed English'}
function ibaWordsFromQuestions(qs){const stop=new Set(('about above after again against all also among an and any are around as at be because been before being between both but by can could did do does each for from further had has have he her here hers him his how i if in into is it its itself just more most no nor not of off on once one only or other our out over own same she should so some such than that the their them then there these they this those through to too under until up very was we were what when where which while who whom why will with would you your').split(' '));const map=new Map();qs.forEach(q=>{const text=[q.question,...(q.options||[]).map(o=>o.text)].join(' ');const tokens=text.match(/[A-Za-z][A-Za-z'-]{4,}/g)||[];[...new Set(tokens.map(ibaNorm).filter(w=>w&&!stop.has(w)))].forEach(w=>{if(!map.has(w))map.set(w,{word:w,bengaliMeaning:'',definition:'',synonyms:[],antonyms:[],example:'',partOfSpeech:'',relatedWords:[],sources:[],difficulty:'unclassified',status:'New'});const x=map.get(w);if(!x.sources.some(s=>s.id===q.id))x.sources.push({id:q.id,number:q.originalNumber,year:q.year,source:q.source})})});return [...map.values()].sort((a,b)=>a.word.localeCompare(b.word))}
function ibaEnsureWords(){if(!IBA.words.length)IBA.words=ibaWordsFromQuestions(IBA.questions);ibaSave()}
function ibaStats(){const q=IBA.questions,w=IBA.words,p=Object.values(IBA.progress),attempts=p.reduce((a,x)=>a+(x.attempts||0),0),correct=p.reduce((a,x)=>a+(x.correct||0),0);return{q:q.length,w:w.length,learned:w.filter(x=>x.status!=='New').length,mastered:w.filter(x=>x.status==='Mastered').length,attempts,accuracy:attempts?Math.round(correct/attempts*100):0,unverified:q.filter(x=>!x.correctAnswer).length}}
function ibaPageHead(kicker,title,sub){return`<div class="page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1><p class="sub">${sub}</p></div></div>`}
function ibaNav(){const tabs=[['dashboard','Dashboard'],['library','Vocabulary Library'],['bank','Past Question Bank'],['practice','Smart Practice'],['games','Vocabulary Games'],['mistakes','Mistake Book'],['revision','Revision Centre'],['mock','Mock Tests'],['analytics','Learning Analytics'],['import','Import Data']];return`<div class="iba-tabs">${tabs.map(([id,n])=>`<button class="btn ${IBA_TAB===id?'pri':''}" onclick="ibaTab('${id}')">${n}</button>`).join('')}</div>`}
function ibaTab(t){IBA_TAB=t;render()}
function ibaStat(v,l){return`<div class="stat-card"><b>${v}</b><small>${l}</small></div>`}
function ibaDashboard(){const s=ibaStats();return`${ibaPageHead('BUSINESS SCHOOL ADMISSION · SEPARATE LEARNING SPACE','IBA Preparation Zone','A dedicated preparation workspace. IBA records and progress are stored separately from your general vocabulary learning.')}${ibaNav()}<div class="iba-stats">${ibaStat(s.q,'Source questions')}${ibaStat(s.w,'Extracted unique words')}${ibaStat(s.learned,'Words in learning')}${ibaStat(s.accuracy+'%','IBA accuracy')}</div><div class="iba-grid">${[['library','Vocabulary Library','Extracted words, source links and learning status'],['bank','Past Question Bank','Browse original questions and filter by year or type'],['practice','Smart Practice','Practice with imported question-bank records'],['games','Vocabulary Games','Seven playable question-based game formats'],['mistakes','Mistake Book','Review questions answered incorrectly'],['revision','Revision Centre','Return to due and weak vocabulary'],['mock','Mock Tests','Timed tests with source and answer verification'],['analytics','Learning Analytics','IBA-only learning and test statistics']].map(([id,n,d])=>`<button class="iba-tile" onclick="ibaTab('${id}')"><span class="iba-tile-icon">${ico('practice')}</span><b>${n}</b><small>${d}</small><span class="iba-arrow">Open →</span></button>`).join('')}</div><section class="card iba-note"><b>Source integrity</b><p>${s.unverified} questions currently have no explicitly verified answer in the supplied text. They remain available for study, but are not silently scored as correct or assigned invented answers.</p><small>Bundled source: DU_IBA_English_MCQ_Only.txt · 345 extracted numbered records</small></section>`}
function ibaFiltered(){const q=IBA.questions;const y=$('#iba-year')?.value||'',src=$('#iba-source')?.value||'',type=$('#iba-type')?.value||'',dif=$('#iba-difficulty')?.value||'';return q.filter(x=>(!y||x.year===y)&&(!src||x.source===src)&&(!type||ibaType(x)===type)&&(!dif||x.difficulty===dif))}
function ibaBank(){const years=[...new Set(IBA.questions.map(x=>x.year).filter(Boolean))].sort().reverse(),sources=[...new Set(IBA.questions.map(x=>x.source))];return`${ibaPageHead('ORIGINAL SOURCE RECORDS','Past Question Bank','Original question text and numbering are preserved. Missing answer keys remain explicitly unverified.')}${ibaNav()}<div class="iba-filters"><select id="iba-year" onchange="ibaDrawBank()"><option value="">All years</option>${years.map(y=>`<option>${y}</option>`).join('')}</select><select id="iba-source" onchange="ibaDrawBank()"><option value="">All sources</option>${sources.map(x=>`<option>${ibaEsc(x)}</option>`).join('')}</select><select id="iba-type" onchange="ibaDrawBank()"><option value="">All question types</option>${[...new Set(IBA.questions.map(ibaType))].sort().map(x=>`<option>${x}</option>`).join('')}</select><select id="iba-difficulty" onchange="ibaDrawBank()"><option value="">All difficulty</option>${['easy','medium','hard','unclassified'].map(x=>`<option value="${x}">${x}</option>`).join('')}</select><input id="iba-search" placeholder="Search question text…" oninput="ibaDrawBank()"></div><p class="sub" id="iba-bank-count">${IBA.questions.length} source records</p><div id="iba-bank-list">${ibaBankRows(IBA.questions.slice(0,30))}</div><button class="btn" onclick="ibaShowMore()">Show next 30</button>`}
function ibaBankRows(rows){if(!rows.length)return'<div class="card">No matching records.</div>';return rows.map(q=>`<article class="card iba-question"><div class="iba-qmeta"><b>Q${q.originalNumber}</b><span>${ibaEsc(q.year||'Year not recorded')}</span><span>${ibaEsc(ibaType(q))}</span><span class="${q.correctAnswer?'iba-verified':'iba-unverified'}">${q.correctAnswer?'Answer recorded':'Answer unverified'}</span></div><p>${ibaEsc(q.question)}</p>${q.options?.length?`<div class="iba-options">${q.options.map(o=>`<span><b>${ibaEsc(o.label)}.</b> ${ibaEsc(o.text)}</span>`).join('')}</div>`:''}<div class="iba-qactions"><button class="btn" onclick="ibaAnswer('${q.id}')">Answer / review</button><button class="btn" onclick="ibaEdit('${q.id}')">Edit verification</button></div></article>`).join('')}
let IBA_BANK_LIMIT=30;
function ibaDrawBank(){const q=ibaFiltered().filter(x=>(!$('#iba-search')?.value||x.question.toLowerCase().includes($('#iba-search').value.toLowerCase())));IBA_BANK_LIMIT=30;$('#iba-bank-count').textContent=`${q.length} matching records`;$('#iba-bank-list').innerHTML=ibaBankRows(q.slice(0,IBA_BANK_LIMIT));}
function ibaShowMore(){const q=ibaFiltered().filter(x=>(!$('#iba-search')?.value||x.question.toLowerCase().includes($('#iba-search').value.toLowerCase())));IBA_BANK_LIMIT+=30;$('#iba-bank-list').innerHTML=ibaBankRows(q.slice(0,IBA_BANK_LIMIT));}
function ibaEdit(id){const q=IBA.questions.find(x=>x.id===id);if(!q)return;const a=prompt('Correct option label (ক/খ/গ/ঘ/A/B/C/D), leave blank if unverified:',q.correctAnswer||'');if(a===null)return;q.correctAnswer=a.trim();q.answerStatus=q.correctAnswer?'user-verified':'unverified';const e=prompt('Explanation (optional):',q.explanation||'');if(e!==null)q.explanation=e;ibaSave();render()}
function ibaAnswer(id){const q=IBA.questions.find(x=>x.id===id);if(!q)return;IBA_SESSION={kind:'single',items:[q],i:0,correct:0,answers:[]};IBA_TAB='practice';render();ibaRenderSession()}
function ibaPractice(){return`${ibaPageHead('ACTIVE RECALL','Smart Practice','Choose a source-backed question set. Unverified answer keys are identified and never included in accuracy scoring.')}${ibaNav()}<div class="card iba-config"><label>Number of questions <select id="iba-practice-count"><option>10</option><option>20</option><option>30</option><option>50</option></select></label><label>Question type <select id="iba-practice-type"><option value="">Mixed</option>${[...new Set(IBA.questions.map(ibaType))].sort().map(x=>`<option>${x}</option>`).join('')}</select></label><button class="btn pri" onclick="ibaStartPractice()">Start practice</button></div><div id="iba-session"></div>`}
function ibaStartPractice(mode='practice'){let pool=IBA.questions.filter(q=>q.options?.length>=2);const type=$('#iba-practice-type')?.value||'';if(type)pool=pool.filter(q=>ibaType(q)===type);if(mode==='mock')pool=pool.filter(q=>q.correctAnswer);const n=Number($('#iba-practice-count')?.value||10);pool=sh(pool).slice(0,n);if(!pool.length){toast(mode==='mock'?'No verified-answer questions are available for a scored mock test. Import or verify answer keys first.':'No usable source questions found.');return}IBA_SESSION={kind:mode,items:pool,i:0,correct:0,answers:[],start:Date.now(),end:mode==='mock'?Date.now()+pool.length*60*1000:0};ibaRenderSession()}
function ibaRenderSession(){const host=$('#iba-session');if(!host||!IBA_SESSION)return;const s=IBA_SESSION;if(s.i>=s.items.length){const scored=s.answers.filter(a=>a.verified),ok=scored.filter(a=>a.ok).length;IBA.history.unshift({date:Date.now(),kind:s.kind,total:s.items.length,scored:scored.length,correct:ok,accuracy:scored.length?Math.round(ok/scored.length*100):null});ibaSave();host.innerHTML=`<div class="card"><h2>${s.kind==='mock'?'Mock test':'Practice'} complete</h2><div class="iba-stats">${ibaStat(ok+'/'+scored.length,'Verified correct')}${ibaStat(scored.length?Math.round(ok/scored.length*100)+'%':'—','Scored accuracy')}${ibaStat(s.items.length-scored.length,'Unverified / unscored')}</div>${s.answers.map(a=>`<p>${a.ok?'✓':'•'} Q${a.q.originalNumber}: ${a.verified?(a.ok?'Correct':'Incorrect'):'Not scored — answer unverified'}</p>`).join('')}<button class="btn pri" onclick="ibaTab('dashboard')">Return to IBA dashboard</button></div>`;return}
const q=s.items[s.i];host.innerHTML=`<div class="card iba-live"><div class="iba-qmeta"><b>${s.i+1}/${s.items.length}</b><span>Source Q${q.originalNumber} · ${ibaEsc(q.year||'Year unknown')}</span><span>${q.correctAnswer?'Verified key':'Unverified key'}</span></div><p>${ibaEsc(q.question)}</p>${(q.options||[]).map(o=>`<button class="btn opt" onclick="ibaPick('${q.id}','${ibaEsc(o.label)}')"><b>${ibaEsc(o.label)}.</b> ${ibaEsc(o.text)}</button>`).join('')}</div>`}
function ibaPick(id,label){const s=IBA_SESSION,q=s.items[s.i];if(!q||q.id!==id)return;const verified=!!q.correctAnswer,ok=verified&&ibaNorm(label)===ibaNorm(q.correctAnswer);s.answers.push({q,choice:label,verified,ok});const p=IBA.progress[q.id]||(IBA.progress[q.id]={attempts:0,correct:0});p.attempts++;if(ok){p.correct++;s.correct++}else{IBA.mistakes[q.id]={last:Date.now(),count:(IBA.mistakes[q.id]?.count||0)+1,choice:label}}ibaSave();s.i++;ibaRenderSession()}
function ibaGames(){const games=[['Meaning Master','Answer source-backed MCQs'],['Synonym Match','Practice synonym-labelled question records'],['Antonym Challenge','Practice antonym-labelled question records'],['Word Decoder','Decode vocabulary in original question contexts'],['Context Detective','Use the full question context'],['Rapid Recall','Short timed question run'],['Odd One Out','Work through odd-word source questions']];return`${ibaPageHead('PLAY TO RECALL','Vocabulary Games','Each game runs on imported IBA source records; no fabricated vocabulary questions are used.')}${ibaNav()}<div class="iba-grid">${games.map((g,i)=>`<button class="iba-tile" onclick="ibaLaunchGame(${i})"><span class="iba-tile-icon">${ico(['spark','match','odd','scramble','practice','speed','levels'][i])}</span><b>${g[0]}</b><small>${g[1]}</small><span class="iba-arrow">Play →</span></button>`).join('')}</div><div id="iba-session"></div>`}
function ibaLaunchGame(i){const types=['','Synonym','Antonym','','','', ''];let pool=IBA.questions.filter(q=>q.options?.length>=2);if(types[i])pool=pool.filter(q=>ibaType(q)===types[i]);if(i===5)pool=sh(pool).slice(0,5);if(i===6)pool=pool.filter(q=>/odd word|odd one/i.test(q.question));if(!pool.length){toast('No matching source questions in the imported dataset yet.');return}IBA_SESSION={kind:'game',items:sh(pool).slice(0,10),i:0,correct:0,answers:[],start:Date.now()};ibaTab('games');setTimeout(ibaRenderSession,0)}
function ibaLibrary(){ibaEnsureWords();const q=$('#iba-word-search')?.value?.toLowerCase()||'';const words=IBA.words.filter(w=>w.word.includes(q));return`${ibaPageHead('SOURCE-LINKED WORDS','IBA Vocabulary Library','Words are extracted from the uploaded question text. Meanings are left blank until enriched from a verified source.')}${ibaNav()}<div class="iba-filters"><input id="iba-word-search" placeholder="Search extracted words…" oninput="ibaDrawWords()"><select id="iba-word-status" onchange="ibaDrawWords()"><option value="">All statuses</option>${['New','Learning','Review','Mastered'].map(x=>`<option>${x}</option>`).join('')}</select></div><p class="sub">${words.length} unique extracted words</p><div id="iba-word-list">${ibaWordRows(words.slice(0,80))}</div>`}
function ibaWordRows(ws){return ws.map(w=>`<article class="card iba-word"><div><b>${ibaEsc(w.word)}</b><small>${w.sources.length} source reference(s) · ${ibaEsc(w.status)}</small><p>${w.bengaliMeaning?ibaEsc(w.bengaliMeaning):'<i>Bangla meaning pending enrichment</i>'} ${w.definition? '· '+ibaEsc(w.definition):''}</p></div><button class="btn" onclick="ibaWordEdit('${ibaEsc(w.word)}')">Enrich</button><select onchange="ibaWordStatus('${ibaEsc(w.word)}',this.value)">${['New','Learning','Review','Mastered'].map(s=>`<option ${w.status===s?'selected':''}>${s}</option>`).join('')}</select></article>`).join('')||'<div class="card">No extracted words found.</div>'}
function ibaDrawWords(){const q=$('#iba-word-search').value.toLowerCase(),st=$('#iba-word-status').value;const ws=IBA.words.filter(w=>w.word.includes(q)&&(!st||w.status===st));$('#iba-word-list').innerHTML=ibaWordRows(ws.slice(0,120))}
function ibaWordEdit(word){const w=IBA.words.find(x=>x.word===word);if(!w)return;w.bengaliMeaning=prompt('Bengali meaning:',w.bengaliMeaning)||w.bengaliMeaning;w.definition=prompt('English definition:',w.definition)||w.definition;w.synonyms=(prompt('Synonyms, comma-separated:',w.synonyms.join(', '))||'').split(',').map(x=>x.trim()).filter(Boolean);w.antonyms=(prompt('Antonyms, comma-separated:',w.antonyms.join(', '))||'').split(',').map(x=>x.trim()).filter(Boolean);ibaSave();render()}
function ibaWordStatus(word,status){const w=IBA.words.find(x=>x.word===word);if(w){w.status=status;w.lastPractice=Date.now();ibaSave()}}
function ibaMistakes(){const ids=Object.keys(IBA.mistakes);return`${ibaPageHead('TARGET YOUR WEAK AREAS','Mistake Book','Questions you answered incorrectly in IBA practice and games.')}${ibaNav()}${ids.length?ids.map(id=>{const q=IBA.questions.find(x=>x.id===id),m=IBA.mistakes[id];return q?`<article class="card iba-question"><b>Q${q.originalNumber} · missed ${m.count} time(s)</b><p>${ibaEsc(q.question)}</p><button class="btn" onclick="ibaAnswer('${q.id}')">Retry</button></article>`:''}).join(''):'<div class="card">No mistakes yet. Complete an IBA practice session to build this list.</div>'}`}
function ibaRevision(){const due=IBA.words.filter(w=>w.status==='Review'||w.status==='Learning');return`${ibaPageHead('SPACED RECALL','Revision Centre','Review words marked Learning or Review. Update status as your recall improves.')}${ibaNav()}${due.length?ibaWordRows(due.slice(0,100)):'<div class="card">No revision words yet. Change extracted word statuses in the Vocabulary Library.</div>'}`}
function ibaMock(){return`${ibaPageHead('EXAM SIMULATION','Mock Tests','Only questions with an explicitly recorded answer key are eligible for scored mock tests. Original source questions are labelled.')}${ibaNav()}<div class="card iba-config"><label>Verified question count <select id="iba-practice-count"><option>5</option><option>10</option><option>20</option><option>30</option></select></label><p class="sub">${IBA.questions.filter(q=>q.correctAnswer&&q.options?.length>=2).length} verified, option-based questions available.</p><button class="btn pri" onclick="ibaStartPractice('mock')">Start timed mock test</button><div id="iba-session"></div></div>`}
function ibaAnalytics(){const s=ibaStats();return`${ibaPageHead('IBA-ONLY PERFORMANCE','Learning Analytics','Statistics are calculated only from the IBA Preparation Zone.')}${ibaNav()}<div class="iba-stats">${ibaStat(s.w,'Unique words')}${ibaStat(s.learned,'Learning words')}${ibaStat(s.mastered,'Mastered words')}${ibaStat(s.accuracy+'%','Accuracy')}</div><div class="card"><h3>Practice history</h3>${IBA.history.length?IBA.history.slice(0,20).map(h=>`<p>${new Date(h.date).toLocaleString()} · ${h.kind} · ${h.correct}/${h.scored} verified · ${h.accuracy===null?'Unscored':h.accuracy+'%'}</p>`).join(''):'No IBA practice history yet.'}</div><div class="card"><h3>Weakest question categories</h3>${Object.entries(IBA.questions.reduce((a,q)=>{const k=ibaType(q);a[k]=(a[k]||0)+(IBA.mistakes[q.id]?1:0);return a},{})).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<p>${ibaEsc(k)} · ${v} mistakes</p>`).join('')||'No category data yet.'}</div>`}
function ibaImport(){return`${ibaPageHead('DATA MANAGEMENT','Import IBA Data','Import JSON, CSV or plain text extracted from PDFs. Records are validated and duplicate IDs/questions are skipped with a visible summary.')}${ibaNav()}<div class="card iba-import"><input type="file" id="iba-file" accept=".json,.csv,.txt,.md"><button class="btn pri" onclick="ibaImportFile()">Validate & import</button><button class="btn" onclick="ibaExport()">Export IBA backup (JSON)</button><div id="iba-import-result"></div><p class="sub">JSON accepts an array or {records:[...]}. CSV expects question, year, source, options, correctAnswer, explanation, topic, difficulty. Text imports preserve each numbered line as an unverified question until reviewed.</p></div>`}
function ibaImportFile(){const f=$('#iba-file').files[0];if(!f){toast('Choose a dataset file first.');return}const r=new FileReader();r.onload=()=>{try{let rows=[],txt=String(r.result);if(f.name.endsWith('.json')){const j=JSON.parse(txt);rows=Array.isArray(j)?j:(j.records||[])}else if(f.name.endsWith('.csv')){const lines=txt.split(/\r?\n/).filter(Boolean),heads=lines.shift().split(',').map(x=>x.trim());rows=lines.map(line=>{const cells=line.match(/(".*?"|[^,]+)(?=,|$)/g)||[];const o={};heads.forEach((h,i)=>o[h]=(cells[i]||'').replace(/^"|"$/g,''));return o})}else{rows=txt.split(/\r?\n/).map((line,i)=>({originalNumber:i+1,question:line.trim(),source:f.name,year:'',options:[],correctAnswer:'',answerStatus:'unverified'})).filter(x=>x.question)}const valid=[],errors=[];rows.forEach((x,i)=>{if(!x||typeof x.question!=='string'||!x.question.trim()){errors.push(`Row ${i+1}: missing question text`);return}const q={id:x.id||`import-${Date.now()}-${i}`,originalNumber:x.originalNumber||i+1,year:String(x.year||''),source:String(x.source||f.name),question:x.question.trim(),options:Array.isArray(x.options)?x.options:(typeof x.options==='string'?x.options.split('|').map((t,j)=>({label:'ABCDE'[j]||String(j+1),text:t.trim()})):[]),correctAnswer:String(x.correctAnswer||''),answerStatus:x.correctAnswer?'imported-unverified':'unverified',explanation:String(x.explanation||''),topic:String(x.topic||''),difficulty:String(x.difficulty||'unclassified')};valid.push(q)});const known=new Set(IBA.questions.map(q=>q.question.trim().toLowerCase()+'|'+q.source));let added=0,dupes=0;valid.forEach(q=>{const k=q.question.trim().toLowerCase()+'|'+q.source;if(known.has(k)){dupes++;return}known.add(k);IBA.questions.push(q);added++});IBA.words=ibaWordsFromQuestions(IBA.questions);IBA.importLog.unshift({date:Date.now(),file:f.name,valid:valid.length,added,duplicates:dupes,errors:errors.length});ibaSave();$('#iba-import-result').innerHTML=`<div class="card"><b>Import summary</b><p>Valid: ${valid.length} · Added: ${added} · Duplicates: ${dupes} · Errors: ${errors.length}</p>${errors.slice(0,30).map(e=>`<p>${ibaEsc(e)}</p>`).join('')}</div>`}catch(e){$('#iba-import-result').textContent='Import failed: '+e.message}};r.readAsText(f)}
function ibaExport(){download('vocabhub-iba-backup.json',JSON.stringify({questions:IBA.questions,words:IBA.words,progress:IBA.progress,mistakes:IBA.mistakes,history:IBA.history},null,2),'application/json')}
V.iba=()=>{if(!IBA_TAB)IBA_TAB='dashboard';if(IBA_TAB==='dashboard')return ibaDashboard();if(IBA_TAB==='bank')return ibaBank();if(IBA_TAB==='practice')return ibaPractice();if(IBA_TAB==='games')return ibaGames();if(IBA_TAB==='library')return ibaLibrary();if(IBA_TAB==='mistakes')return ibaMistakes();if(IBA_TAB==='revision')return ibaRevision();if(IBA_TAB==='mock')return ibaMock();if(IBA_TAB==='analytics')return ibaAnalytics();if(IBA_TAB==='import')return ibaImport();return ibaDashboard()};
PAGES.splice(PAGES.length-1,0,['iba','IBA Zone','practice']);
PRIMARY.push('iba');
const _ibaTopbar=topbar;topbar=function(v){if(v==='iba'){const pg={1:'IBA Preparation Zone'};return`<header class="topbar"><div class="topbar-context"><span class="topbar-kicker">VOCABHUB / ADMISSION PREPARATION</span><b>IBA Preparation Zone</b></div><div class="topbar-actions"><span class="xp-chip">345 source records</span></div></header>`}return _ibaTopbar(v)};
const _ibaRender=render;render=function(){_ibaRender();if(location.hash==='#iba'&&IBA_SESSION&&['practice','mock','game'].includes(IBA_SESSION.kind))ibaRenderSession()};
ibaEnsureWords();
render();
